namespace
{
	int mapSqlErrorToSqlite(const QSqlError &err)
	{
		if (!err.isValid())
			return SQLITE_OK;

		bool      nativeCodeValid = false;
		const int nativeCode      = err.nativeErrorCode().toInt(&nativeCodeValid);
		if (nativeCodeValid && nativeCode > 0)
			return nativeCode & 0xff;

		const QString text = err.text().toLower();
		if (text.contains(QStringLiteral("locked")) || text.contains(QStringLiteral("busy")))
			return SQLITE_BUSY;
		if (text.contains(QStringLiteral("readonly")))
			return SQLITE_READONLY;
		return SQLITE_ERROR;
	}

	int applySqliteWalAndNormalSynchronous(const QSqlDatabase &db, QString &errorMessage)
	{
		if (!db.isValid() || !db.isOpen())
		{
			errorMessage = QStringLiteral("Database connection is not open.");
			return SQLITE_ERROR;
		}

		QSqlQuery query(db);
		if (!query.exec(QStringLiteral("PRAGMA journal_mode=WAL")))
		{
			errorMessage = query.lastError().text();
			return mapSqlErrorToSqlite(query.lastError());
		}

		const QString mode = query.next() ? query.value(0).toString().trimmed() : QString();
		if (mode.compare(QStringLiteral("wal"), Qt::CaseInsensitive) != 0)
		{
			errorMessage = QStringLiteral("PRAGMA journal_mode returned '%1' instead of 'wal'.").arg(mode);
			return SQLITE_ERROR;
		}

		if (!query.exec(QStringLiteral("PRAGMA synchronous=NORMAL")))
		{
			errorMessage = query.lastError().text();
			return mapSqlErrorToSqlite(query.lastError());
		}

		return SQLITE_OK;
	}

	int mapVariantTypeToSqlite(const QVariant &value)
	{
		if (value.isNull())
			return SQLITE_NULL;
		switch (value.typeId())
		{
		case QMetaType::Int:
		case QMetaType::UInt:
		case QMetaType::LongLong:
		case QMetaType::ULongLong:
		case QMetaType::Short:
		case QMetaType::UShort:
		case QMetaType::Char:
		case QMetaType::UChar:
			return SQLITE_INTEGER;
		case QMetaType::Double:
		case QMetaType::Float:
			return SQLITE_FLOAT;
		case QMetaType::QByteArray:
			return SQLITE_BLOB;
		default:
			return SQLITE_TEXT;
		}
	}

	enum class SqliteCompleteState : quint8
	{
		Invalid,
		Start,
		Normal,
		Explain,
		Create,
		Trigger,
		Semicolon,
		End
	};

	enum class SqliteCompleteToken : quint8
	{
		Semicolon,
		Whitespace,
		Other,
		Explain,
		Create,
		Temporary,
		Trigger,
		End
	};

	// Keep statement-boundary recognition identical to SQLite's sqlite3_complete() state machine. This permits
	// QSqlQuery to reproduce sqlite3_exec() sequencing without mixing a Qt-owned connection with another SQLite.
	constexpr std::array<std::array<SqliteCompleteState, 8>, 8> kSqliteCompleteTransitions{
	    {{SqliteCompleteState::Start, SqliteCompleteState::Invalid, SqliteCompleteState::Normal,
	      SqliteCompleteState::Explain, SqliteCompleteState::Create, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal},
	     {SqliteCompleteState::Start, SqliteCompleteState::Start, SqliteCompleteState::Normal,
	      SqliteCompleteState::Explain, SqliteCompleteState::Create, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal},
	     {SqliteCompleteState::Start, SqliteCompleteState::Normal, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal},
	     {SqliteCompleteState::Start, SqliteCompleteState::Explain, SqliteCompleteState::Explain,
	      SqliteCompleteState::Normal, SqliteCompleteState::Create, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal},
	     {SqliteCompleteState::Start, SqliteCompleteState::Create, SqliteCompleteState::Normal,
	      SqliteCompleteState::Normal, SqliteCompleteState::Normal, SqliteCompleteState::Create,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Normal},
	     {SqliteCompleteState::Semicolon, SqliteCompleteState::Trigger, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Trigger, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Trigger},
	     {SqliteCompleteState::Semicolon, SqliteCompleteState::Semicolon, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Trigger, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::End},
	     {SqliteCompleteState::Start, SqliteCompleteState::End, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Trigger, SqliteCompleteState::Trigger,
	      SqliteCompleteState::Trigger, SqliteCompleteState::Trigger}}
    };

	bool isSqliteIdentifierCodeUnit(const QChar codeUnit)
	{
		const ushort value = codeUnit.unicode();
		return value >= 0x80 || (value >= 'a' && value <= 'z') || (value >= 'A' && value <= 'Z') ||
		       (value >= '0' && value <= '9') || value == '_' || value == '$';
	}

	bool sqliteKeywordEquals(const QString &sql, const qsizetype offset, const qsizetype length,
	                         const char *keyword)
	{
		for (qsizetype i = 0; i < length; ++i)
		{
			ushort value = sql.at(offset + i).unicode();
			if (value >= 'A' && value <= 'Z')
				value = static_cast<ushort>(value - 'A' + 'a');
			if (value != static_cast<unsigned char>(keyword[i]))
				return false;
		}
		return keyword[length] == '\0';
	}

	SqliteCompleteToken sqliteKeywordToken(const QString &sql, const qsizetype offset, const qsizetype length)
	{
		if (length == 3 && sqliteKeywordEquals(sql, offset, length, "end"))
			return SqliteCompleteToken::End;
		if (length == 4 && sqliteKeywordEquals(sql, offset, length, "temp"))
			return SqliteCompleteToken::Temporary;
		if (length == 6 && sqliteKeywordEquals(sql, offset, length, "create"))
			return SqliteCompleteToken::Create;
		if (length == 7 && sqliteKeywordEquals(sql, offset, length, "explain"))
			return SqliteCompleteToken::Explain;
		if (length == 7 && sqliteKeywordEquals(sql, offset, length, "trigger"))
			return SqliteCompleteToken::Trigger;
		if (length == 9 && sqliteKeywordEquals(sql, offset, length, "temporary"))
			return SqliteCompleteToken::Temporary;
		return SqliteCompleteToken::Other;
	}

	template <typename Visitor> bool visitSqliteExecStatements(const QString &sqlText, Visitor &&visitor)
	{
		const qsizetype     nul               = sqlText.indexOf(QChar::Null);
		const qsizetype     sqlSize           = nul < 0 ? sqlText.size() : nul;
		SqliteCompleteState state             = SqliteCompleteState::Invalid;
		qsizetype           statementStart    = 0;
		bool                statementHasToken = false;

		for (qsizetype offset = 0; offset < sqlSize; ++offset)
		{
			SqliteCompleteToken token = SqliteCompleteToken::Other;
			switch (sqlText.at(offset).unicode())
			{
			case ';':
				token = SqliteCompleteToken::Semicolon;
				break;
			case ' ':
			case '\r':
			case '\t':
			case '\n':
			case '\f':
				token = SqliteCompleteToken::Whitespace;
				break;
			case '/':
				if (offset + 1 < sqlSize && sqlText.at(offset + 1) == QLatin1Char('*'))
				{
					offset += 2;
					while (offset < sqlSize &&
					       (sqlText.at(offset) != QLatin1Char('*') || offset + 1 >= sqlSize ||
					        sqlText.at(offset + 1) != QLatin1Char('/')))
						++offset;
					if (offset < sqlSize)
						++offset;
					else
						offset = sqlSize - 1;
					token = SqliteCompleteToken::Whitespace;
				}
				break;
			case '-':
				if (offset + 1 < sqlSize && sqlText.at(offset + 1) == QLatin1Char('-'))
				{
					while (offset + 1 < sqlSize && sqlText.at(offset + 1) != QLatin1Char('\n'))
						++offset;
					token = SqliteCompleteToken::Whitespace;
				}
				break;
			case '[':
				while (offset + 1 < sqlSize && sqlText.at(offset + 1) != QLatin1Char(']'))
					++offset;
				if (offset + 1 < sqlSize)
					++offset;
				break;
			case '`':
			case '"':
			case '\'':
			{
				const QChar quote = sqlText.at(offset);
				while (offset + 1 < sqlSize && sqlText.at(offset + 1) != quote)
					++offset;
				if (offset + 1 < sqlSize)
					++offset;
				break;
			}
			default:
				if (isSqliteIdentifierCodeUnit(sqlText.at(offset)))
				{
					const qsizetype identifierStart = offset;
					while (offset + 1 < sqlSize && isSqliteIdentifierCodeUnit(sqlText.at(offset + 1)))
						++offset;
					token = sqliteKeywordToken(sqlText, identifierStart, offset - identifierStart + 1);
				}
				break;
			}

			state = kSqliteCompleteTransitions.at(static_cast<std::size_t>(state))
			            .at(static_cast<std::size_t>(token));
			if (token != SqliteCompleteToken::Whitespace && token != SqliteCompleteToken::Semicolon)
				statementHasToken = true;

			if (token == SqliteCompleteToken::Semicolon && state == SqliteCompleteState::Start)
			{
				if (statementHasToken &&
				    !visitor(sqlText.sliced(statementStart, offset - statementStart + 1)))
					return false;
				statementStart    = offset + 1;
				statementHasToken = false;
			}
		}

		return !statementHasToken || visitor(sqlText.sliced(statementStart, sqlSize - statementStart));
	}
} // namespace

namespace
{
	QStringList sqlRecordColumnNames(const QSqlRecord &record, const int columnCount)
	{
		QStringList names;
		names.reserve(columnCount);
		for (int index = 0; index < columnCount; ++index)
			names.append(record.fieldName(index));
		return names;
	}
} // namespace

void WorldRuntime::refreshDatabaseChangeCounters(DatabaseEntry &entry)
{
	QSqlQuery query(entry.db);
	if (!query.exec(QStringLiteral("SELECT total_changes(), changes(), last_insert_rowid()")) ||
	    !query.next())
	{
		return;
	}
	entry.totalChanges    = query.value(0).toInt();
	entry.changes         = query.value(1).toInt();
	entry.lastInsertRowid = query.value(2).toString();
}

int WorldRuntime::databaseOpen(const QString &name, const QString &filename, int flags)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, SQLITE_ERROR, [this, name, filename, flags]
		                          { return databaseOpen(name, filename, flags); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseOpen");
	const bool isMemory = (flags & SQLITE_OPEN_MEMORY) != 0 || filename == QStringLiteral(":memory:");
	QString    diskName = filename;
	if (!isMemory)
	{
		QString error;
		if (!QMudPluginPathUtils::resolveInsideQmudHome(m_startupDirectory, filename, &diskName, &error))
			return SQLITE_CANTOPEN;
	}
	const auto it = m_databases.find(name);
	if (it != m_databases.end())
	{
		if (it->diskName == diskName)
			return SQLITE_OK;
		return kDbErrorDatabaseAlreadyExists;
	}

	if (!isMemory && (flags & SQLITE_OPEN_CREATE) == 0 && !QFileInfo::exists(diskName))
		return SQLITE_CANTOPEN;

	static std::atomic<quint64> connectionCounter{0};
	DatabaseEntry               entry;
	entry.diskName = diskName;
	entry.connectionName =
	    QStringLiteral("world_db_%1").arg(connectionCounter.fetch_add(1, std::memory_order_relaxed) + 1);
	entry.db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), entry.connectionName);
	entry.db.setDatabaseName(isMemory ? QStringLiteral(":memory:") : diskName);
	if (flags & SQLITE_OPEN_READONLY)
		entry.db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
	if (!entry.db.open())
	{
		entry.lastError        = mapSqlErrorToSqlite(entry.db.lastError());
		entry.lastErrorMessage = entry.db.lastError().text();
		entry.db               = QSqlDatabase();
		QSqlDatabase::removeDatabase(entry.connectionName);
		return entry.lastError;
	}

	if (!isMemory && (flags & SQLITE_OPEN_READONLY) == 0)
	{
		entry.lastError = applySqliteWalAndNormalSynchronous(entry.db, entry.lastErrorMessage);
		if (entry.lastError != SQLITE_OK)
		{
			entry.db.close();
			entry.db = QSqlDatabase();
			QSqlDatabase::removeDatabase(entry.connectionName);
			return entry.lastError;
		}
	}

	refreshDatabaseChangeCounters(entry);
	m_databases.insert(name, entry);
	patchLuaCallbackDatabaseSnapshot(name, true);
	return SQLITE_OK;
}

int WorldRuntime::databaseClose(const QString &name)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, kDbErrorIdNotFound, [this, name] { return databaseClose(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseClose");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (it->stmtPrepared)
	{
		it->stmt->finish();
		it->stmtPrepared = false;
		it->stmt.clear();
	}
	it->db.close();
	const QString connectionName = it->connectionName;
	m_databases.erase(it);
	QSqlDatabase::removeDatabase(connectionName);
	patchLuaCallbackDatabaseSnapshot(name, true);
	return SQLITE_OK;
}

int WorldRuntime::databasePrepare(const QString &name, const QString &sql)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, kDbErrorIdNotFound,
		                          [this, name, sql] { return databasePrepare(name, sql); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databasePrepare");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (it->stmtPrepared)
		return kDbErrorHavePreparedStatement;

	it->validRow = false;
	it->columns  = 0;
	it->columnNames.clear();
	const auto patchSnapshot = qScopeGuard([this, name] { patchLuaCallbackDatabaseSnapshot(name); });
	it->stmt                 = QSharedPointer<QSqlQuery>::create(it->db);
	if (!it->stmt->prepare(sql))
	{
		it->lastError        = mapSqlErrorToSqlite(it->stmt->lastError());
		it->lastErrorMessage = it->stmt->lastError().text();
		return it->lastError;
	}
	it->stmtPrepared = true;
	it->stmtExecuted = false;
	it->lastError    = SQLITE_OK;
	it->lastErrorMessage.clear();
	const QSqlRecord record = it->stmt->record();
	it->columns             = record.count();
	it->columnNames         = sqlRecordColumnNames(record, it->columns);
	return SQLITE_OK;
}

int WorldRuntime::databaseFinalize(const QString &name)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, kDbErrorIdNotFound, [this, name] { return databaseFinalize(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseFinalize");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (!it->stmtPrepared)
		return kDbErrorNoPreparedStatement;

	it->stmt->finish();
	it->stmt.clear();
	it->stmtPrepared = false;
	it->stmtExecuted = false;
	it->validRow     = false;
	it->columns      = 0;
	it->columnNames.clear();
	refreshDatabaseChangeCounters(it.value());
	patchLuaCallbackDatabaseSnapshot(name);
	return SQLITE_OK;
}

int WorldRuntime::databaseReset(const QString &name)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, kDbErrorIdNotFound, [this, name] { return databaseReset(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseReset");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (!it->stmtPrepared)
		return kDbErrorNoPreparedStatement;
	it->stmt->finish();
	it->stmtExecuted = false;
	it->validRow     = false;
	refreshDatabaseChangeCounters(it.value());
	patchLuaCallbackDatabaseSnapshot(name);
	return SQLITE_OK;
}

int WorldRuntime::databaseColumns(const QString &name) const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), kDbErrorIdNotFound,
		                          [this, name] { return databaseColumns(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseColumns");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (!it->stmtPrepared)
		return kDbErrorNoPreparedStatement;
	return it->columns;
}

int WorldRuntime::databaseStep(const QString &name)
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(this, kDbErrorIdNotFound, [this, name] { return databaseStep(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseStep");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (!it->stmtPrepared)
		return kDbErrorNoPreparedStatement;
	const auto patchSnapshot = qScopeGuard([this, name] { patchLuaCallbackDatabaseSnapshot(name); });

	bool       statementStarted = false;
	if (!it->stmtExecuted)
	{
		if (!it->stmt->exec())
		{
			it->lastError        = mapSqlErrorToSqlite(it->stmt->lastError());
			it->lastErrorMessage = it->stmt->lastError().text();
			it->validRow         = false;
			refreshDatabaseChangeCounters(it.value());
			return it->lastError;
		}
		it->stmtExecuted        = true;
		const QSqlRecord record = it->stmt->record();
		it->columns             = record.count();
		it->columnNames         = sqlRecordColumnNames(record, it->columns);
		statementStarted        = true;
	}

	if (it->stmt->next())
	{
		it->validRow  = true;
		it->lastError = SQLITE_ROW;
		it->lastErrorMessage.clear();
		if (statementStarted)
			refreshDatabaseChangeCounters(it.value());
		return SQLITE_ROW;
	}

	it->validRow = false;
	if (const QSqlError stepError = it->stmt->lastError(); stepError.isValid())
	{
		it->lastError        = mapSqlErrorToSqlite(stepError);
		it->lastErrorMessage = stepError.text();
		refreshDatabaseChangeCounters(it.value());
		return it->lastError;
	}
	it->lastError = SQLITE_DONE;
	it->lastErrorMessage.clear();
	refreshDatabaseChangeCounters(it.value());
	return SQLITE_DONE;
}

QString WorldRuntime::databaseError(const QString &name) const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), QStringLiteral("database error"),
		                          [this, name] { return databaseError(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseError");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return QStringLiteral("database id not found");
	if (!it->db.isValid() || !it->db.isOpen())
		return QStringLiteral("database not open");

	switch (it->lastError)
	{
	case SQLITE_OK:
		return QStringLiteral("not an error");
	case SQLITE_ROW:
		return QStringLiteral("row ready");
	case SQLITE_DONE:
		return QStringLiteral("finished");
	case kDbErrorIdNotFound:
		return QStringLiteral("database id not found");
	case kDbErrorNotOpen:
		return QStringLiteral("database not open");
	case kDbErrorHavePreparedStatement:
		return QStringLiteral("already have prepared statement");
	case kDbErrorNoPreparedStatement:
		return QStringLiteral("do not have prepared statement");
	case kDbErrorNoValidRow:
		return QStringLiteral("do not have a valid row");
	case kDbErrorDatabaseAlreadyExists:
		return QStringLiteral("database already exists under a different disk name");
	case kDbErrorColumnOutOfRange:
		return QStringLiteral("column count out of valid range");
	default:
		return it->lastErrorMessage.isEmpty() ? QStringLiteral("database error") : it->lastErrorMessage;
	}
}

QString WorldRuntime::databaseColumnName(const QString &name, int column) const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), QString(),
		                          [this, name, column] { return databaseColumnName(name, column); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseColumnName");
	const auto it = m_databases.find(name);
	if (it == m_databases.end() || !it->db.isValid() || !it->db.isOpen() || !it->stmtPrepared || column < 1 ||
	    column > it->columns)
		return {};
	return it->stmt->record().fieldName(column - 1);
}

QString WorldRuntime::databaseColumnText(const QString &name, int column, bool *ok) const
{
	if (ok)
		*ok = false;
	if (QThread::currentThread() != thread())
	{
		const auto resolved =
		    qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), std::pair<QString, bool>{{}, false},
		                       [this, name, column]
		                       {
			                       bool    localOk = false;
			                       QString value   = databaseColumnText(name, column, &localOk);
			                       return std::pair<QString, bool>{value, localOk};
		                       });
		if (ok)
			*ok = resolved.second;
		return resolved.first;
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseColumnText");
	const auto it = m_databases.find(name);
	if (it == m_databases.end() || !it->db.isValid() || !it->db.isOpen() || !it->stmtPrepared ||
	    !it->validRow || column < 1 || column > it->columns)
		return {};
	const QVariant value = it->stmt->value(column - 1);
	if (value.isNull())
		return {};
	if (ok)
		*ok = true;
	return value.toString();
}

bool WorldRuntime::databaseColumnValue(const QString &name, int column, QVariant &value) const
{
	if (QThread::currentThread() != thread())
	{
		const auto resolved =
		    qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), std::pair<bool, QVariant>{false, QVariant()},
		                       [this, name, column]
		                       {
			                       QVariant   localValue;
			                       const bool found = databaseColumnValue(name, column, localValue);
			                       return std::pair<bool, QVariant>{found, localValue};
		                       });
		if (resolved.first)
			value = resolved.second;
		return resolved.first;
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseColumnValue");
	const auto it = m_databases.find(name);
	if (it == m_databases.end() || !it->db.isValid() || !it->db.isOpen() || !it->stmtPrepared ||
	    !it->validRow || column < 1 || column > it->columns)
		return false;

	value = it->stmt->value(column - 1);
	return true;
}

int WorldRuntime::databaseColumnType(const QString &name, int column) const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), kDbErrorIdNotFound,
		                          [this, name, column] { return databaseColumnType(name, column); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseColumnType");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	if (!it->stmtPrepared)
		return kDbErrorNoPreparedStatement;
	if (!it->validRow)
		return kDbErrorNoValidRow;
	if (column < 1 || column > it->columns)
		return kDbErrorColumnOutOfRange;
	return mapVariantTypeToSqlite(it->stmt->value(column - 1));
}

int WorldRuntime::databaseTotalChanges(const QString &name) const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), kDbErrorIdNotFound,
		                          [this, name] { return databaseTotalChanges(name); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::databaseTotalChanges");
	const auto it = m_databases.find(name);
	if (it == m_databases.end())
		return kDbErrorIdNotFound;
	if (!it->db.isValid() || !it->db.isOpen())
		return kDbErrorNotOpen;
	return it->totalChanges;
}

