int WorldRuntime::savePluginState(const QString &pluginId, bool scripted, QString *error)
{
	if (QThread::currentThread() != thread())
	{
		const auto resolved = qmudInvokeMethodOr(this, std::pair<int, QString>{ePluginCouldNotSaveState, {}},
		                                         [this, pluginId, scripted, needsError = (error != nullptr)]
		                                         {
			                                         QString   localError;
			                                         QString  *errorPtr = needsError ? &localError : nullptr;
			                                         const int result =
			                                             savePluginState(pluginId, scripted, errorPtr);
			                                         return std::pair<int, QString>{result, localError};
		                                         });
		if (error)
			*error = resolved.second;
		return resolved.first;
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::savePluginState");
	if (pluginId.isEmpty())
		return eNotAPlugin;
	const int index = findPluginIndex(m_plugins, pluginId);
	if (index < 0)
		return eNoSuchPlugin;
	const QString resolvedPluginId = m_plugins.at(index).attributes.value(QStringLiteral("id"));
	return savePluginStateForPlugin(resolvedPluginId, scripted, error);
}

void WorldRuntime::savePluginStateAsync(const QString &pluginId, const bool scripted,
                                        std::function<void(int)> completion)
{
	if (QThread::currentThread() != thread())
	{
		const QPointer<WorldRuntime> runtime(this);
		qmudInvokeMethodQueued(this,
		                       [runtime, pluginId, scripted, completion = std::move(completion)]() mutable
		                       {
			                       if (runtime)
				                       runtime->savePluginStateAsync(pluginId, scripted,
				                                                     std::move(completion));
		                       });
		return;
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::savePluginStateAsync");
	if (pluginId.isEmpty())
	{
		if (completion)
			completion(eNotAPlugin);
		return;
	}
	const int index = findPluginIndex(m_plugins, pluginId);
	if (index < 0)
	{
		if (completion)
			completion(eNoSuchPlugin);
		return;
	}
	const QString resolvedPluginId = m_plugins.at(index).attributes.value(QStringLiteral("id"));
	savePluginStateForPluginContinuable(resolvedPluginId, scripted, std::move(completion));
}

int WorldRuntime::savePluginStateForPlugin(const QString &pluginId, const bool scripted, QString *error)
{
	QString                           resolvedPluginId;
	QSharedPointer<LuaCallbackEngine> callbackEngine;
	if (const std::optional<int> earlyResult =
	        preparePluginStateSave(pluginId, scripted, resolvedPluginId, callbackEngine))
	{
		return *earlyResult;
	}
	if (callbackEngine)
		dispatchSingleEngineNoArgPluginCallback(
		    callbackEngine, LuaCallbackEvent::SaveState,
		    WorldRuntime::PluginCallbackCompletionPolicy::CompletionRequired);
	return finishPluginStateSave(resolvedPluginId, scripted, error);
}

std::optional<int> WorldRuntime::preparePluginStateSave(const QString &pluginId, const bool scripted,
                                                        QString                           &resolvedPluginId,
                                                        QSharedPointer<LuaCallbackEngine> &callbackEngine)
{
	const int initialIndex = findPluginIndex(m_plugins, pluginId);
	if (initialIndex < 0)
		return scripted ? eNoSuchPlugin : eOK;
	const QString worldId = m_worldAttributes.value(QStringLiteral("id")).trimmed();
	if (worldId.isEmpty())
		return scripted ? ePluginCouldNotSaveState : eOK;
	if (m_stateFilesDirectory.isEmpty())
		return scripted ? ePluginCouldNotSaveState : eOK;
	QString base = m_stateFilesDirectory;
	if (!base.endsWith('/') && !base.endsWith('\\'))
		base += '/';
	const QDir baseDir(base);
	if (!baseDir.exists())
		return scripted ? ePluginCouldNotSaveState : eOK;

	{
		Plugin &plugin = m_plugins[initialIndex];
		if (!scripted && !plugin.saveState)
			return eOK;
		if (plugin.savingStateNow)
			return ePluginCouldNotSaveState;
		resolvedPluginId = plugin.attributes.value(QStringLiteral("id"));
		if (resolvedPluginId.isEmpty())
			return scripted ? ePluginCouldNotSaveState : eOK;
		plugin.savingStateNow = true;
		callbackEngine        = plugin.lua;
	}
	return std::nullopt;
}

void WorldRuntime::savePluginStateForPluginContinuable(const QString &pluginId, const bool scripted,
                                                       std::function<void(int)> completion)
{
	QString                           resolvedPluginId;
	QSharedPointer<LuaCallbackEngine> callbackEngine;
	if (const std::optional<int> earlyResult =
	        preparePluginStateSave(pluginId, scripted, resolvedPluginId, callbackEngine))
	{
		if (completion)
			completion(*earlyResult);
		return;
	}
	const QPointer<WorldRuntime> runtime(this);
	auto                         finish = [runtime, resolvedPluginId, scripted,
	                                       completion = std::move(completion)](const bool cancelled) mutable
	{
		if (!runtime)
			return;
		if (cancelled)
		{
			if (const int index = findPluginIndex(runtime->m_plugins, resolvedPluginId); index >= 0)
				runtime->m_plugins[index].savingStateNow = false;
		}
		const int result = cancelled ? (scripted ? ePluginCouldNotSaveState : eOK)
		                             : runtime->finishPluginStateSave(resolvedPluginId, scripted, nullptr);
		if (completion)
			completion(result);
	};
	if (callbackEngine)
	{
		LuaBatchDispatchRequest request;
		request.kind          = LuaBatchDispatchKind::NoArgs;
		request.callbackEvent = LuaCallbackEvent::SaveState;
		request.engines       = {callbackEngine};
		request.functionName  = luaCallbackEventFunctionName(request.callbackEvent);
		request.defaultResult = true;
		if (!dispatchPluginCallbackContinuable(request, finish))
			return;
	}
	finish(false);
}

int WorldRuntime::finishPluginStateSave(const QString &resolvedPluginId, const bool scripted, QString *error)
{
	const QString worldId = m_worldAttributes.value(QStringLiteral("id")).trimmed();
	if (worldId.isEmpty() || m_stateFilesDirectory.isEmpty())
		return scripted ? ePluginCouldNotSaveState : eOK;
	QString base = m_stateFilesDirectory;
	if (!base.endsWith('/') && !base.endsWith('\\'))
		base += '/';
	if (!QDir(base).exists())
		return scripted ? ePluginCouldNotSaveState : eOK;

	const int currentIndex = findPluginIndex(m_plugins, resolvedPluginId);
	if (currentIndex < 0)
		return scripted ? ePluginCouldNotSaveState : eOK;
	Plugin &currentPlugin                  = m_plugins[currentIndex];
	currentPlugin.savingStateNow           = false;
	const QMap<QString, QString> variables = currentPlugin.variables;

	const QString                stateFile = base + worldId + "-" + resolvedPluginId + "-state.xml";
	QSaveFile                    file(stateFile);
	if (!file.open(QIODevice::WriteOnly | QIODevice::Text))
	{
		if (error)
			*error = QStringLiteral("Unable to create plugin state file: %1").arg(stateFile);
		return scripted ? ePluginCouldNotSaveState : eOK;
	}

	QTextStream out(&file);
	out.setEncoding(QStringConverter::Utf8);
	const auto      nl = QStringLiteral("\r\n");

	const QDateTime now     = QDateTime::currentDateTime();
	const QString   savedOn = QLocale::system().toString(now, QStringLiteral("dddd, MMMM dd, yyyy, h:mm AP"));

	out << R"(<?xml version="1.0" encoding="utf-8"?>)" << nl;
	out << "<!DOCTYPE qmud>" << nl;
	out << "<!-- Saved on " << fixHtmlString(savedOn) << " -->" << nl;
	out << "<!-- QMud version " << kVersionString << " -->" << nl;
	out << "<!-- Written by Panagiotis Kalogiratos -->" << nl;
	out << "<!-- Home Page: https://github.com/Nodens-/QMud -->" << nl;
	out << "<qmud>" << nl;
	out << nl << "<!-- variables -->" << nl;
	out << "<variables>" << nl;

	for (auto it = variables.constBegin(); it != variables.constEnd(); ++it)
	{
		out << "  <variable name=\"" << fixHtmlString(it.key()) << "\">" << fixHtmlMultilineString(it.value())
		    << "</variable>" << nl;
	}

	out << "</variables>" << nl;
	out << "</qmud>" << nl;

	if (!file.commit())
	{
		if (error)
			*error = QStringLiteral("Unable to write plugin state file: %1").arg(stateFile);
		return scripted ? ePluginCouldNotSaveState : eOK;
	}

	return eOK;
}

void WorldRuntime::sortPluginsBySequence()
{
	std::ranges::stable_sort(m_plugins,
	                         [](const Plugin &a, const Plugin &b) { return a.sequence < b.sequence; });
}

const QList<WorldRuntime::Include> &WorldRuntime::includes() const
{
	return m_includes;
}

QString WorldRuntime::comments() const
{
	return m_comments;
}

void WorldRuntime::addLine(const QString &text, int flags, bool hardReturn, const QDateTime &time)
{
	if (m_sessionStateOutputBufferSealed)
		return;

	LineEntry entry;
	entry.text       = text;
	entry.flags      = flags;
	entry.hardReturn = hardReturn;
	entry.spans.clear();
	entry.time       = time.toUTC();
	entry.lineNumber = m_nextLineNumber++;
	if (m_lineTimer.isValid())
	{
		entry.ticks   = static_cast<double>(m_lineTimer.nsecsElapsed()) / 1000000000.0;
		entry.elapsed = entry.ticks;
	}
	else
	{
		const double fallback = (m_worldStartTime.isValid() && entry.time.isValid())
		                            ? static_cast<double>(m_worldStartTime.msecsTo(entry.time)) / 1000.0
		                            : 0.0;
		entry.ticks           = fallback;
		entry.elapsed         = fallback;
	}
	appendOutputLine(std::move(entry));
	const int removedHeadCount = enforceOutputLineLimit();
	invalidateLuaCallbackLineBufferSnapshot();
	if (!m_lines.isEmpty())
		notifyOutputViewLineAppended(removedHeadCount);
}

void WorldRuntime::addLine(const QString &text, int flags, const QVector<StyleSpan> &spans, bool hardReturn,
                           const QDateTime &time)
{
	if (m_sessionStateOutputBufferSealed)
		return;

	LineEntry entry;
	entry.text       = text;
	entry.flags      = flags;
	entry.hardReturn = hardReturn;
	entry.spans      = spans;
	entry.time       = time.toUTC();
	entry.lineNumber = m_nextLineNumber++;
	if (m_lineTimer.isValid())
	{
		entry.ticks   = static_cast<double>(m_lineTimer.nsecsElapsed()) / 1000000000.0;
		entry.elapsed = entry.ticks;
	}
	else
	{
		const double fallback = (m_worldStartTime.isValid() && entry.time.isValid())
		                            ? static_cast<double>(m_worldStartTime.msecsTo(entry.time)) / 1000.0
		                            : 0.0;
		entry.ticks           = fallback;
		entry.elapsed         = fallback;
	}
	appendOutputLine(std::move(entry));
	const int removedHeadCount = enforceOutputLineLimit();
	invalidateLuaCallbackLineBufferSnapshot();
	if (!m_lines.isEmpty())
		notifyOutputViewLineAppended(removedHeadCount);
}

bool WorldRuntime::commitPendingIncomingPartialLineStorage(QString *committedText)
{
	if (QThread::currentThread() != thread())
	{
		return qmudInvokeMethodOr(this, false, [this, committedText]
		                          { return commitPendingIncomingPartialLineStorage(committedText); });
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::commitPendingIncomingPartialLineStorage");
	if (m_sessionStateOutputBufferSealed)
		return false;
	if (m_partialLineText.isEmpty() && m_partialLineSpans.isEmpty())
		return false;

	QString            text  = m_partialLineText;
	QVector<StyleSpan> spans = m_partialLineSpans;
	if (committedText)
		*committedText = text;
	m_partialLineText.clear();
	m_partialLineSpans.clear();
	m_pendingCarriageReturnOverwrite = false;
	setIncomingPartialLineRevision(m_incomingPartialLineRevision + 1);

	const bool                  serverSideWrapActive = isConnected() && m_telnet.isNawsNegotiated();
	const FixedColumnWrapConfig wrapConfig =
	    serverSideWrapActive
	        ? FixedColumnWrapConfig{}
	        : localOutputWrapConfig(m_worldAttributes, serverSideWrapActive, m_telnet.windowColumns());
	if (wrapConfig.enabled && !text.isEmpty())
	{
		if (spans.isEmpty())
			wrapPlainLineForColumn(text, wrapConfig.wrapColumn, wrapConfig.indentParas);
		else
			wrapStyledLineForColumn(text, spans, wrapConfig.wrapColumn, wrapConfig.indentParas);
	}

	if (spans.isEmpty())
		addLine(text, LineOutput, true);
	else
		addLine(text, LineOutput, spans, true);
	return true;
}

int WorldRuntime::maxOutputLinesLimit() const
{
	bool      ok         = false;
	const int configured = m_worldAttributes.value(QStringLiteral("max_output_lines")).toInt(&ok);
	if (!ok || configured <= 0)
		return 0;
	return qBound(0, configured, 500000);
}

int WorldRuntime::enforceOutputLineLimit()
{
	if (m_sessionStateOutputBufferSealed)
		return 0;

	const int maxLines = maxOutputLinesLimit();
	if (maxLines <= 0 || m_lines.size() <= maxLines)
		return 0;

	return removeOutputLineRange(0, safeQSizeToInt(m_lines.size() - maxLines));
}

const IndexedRingBuffer<WorldRuntime::LineEntry> &WorldRuntime::lines() const
{
	return m_lines;
}

bool WorldRuntime::outputLineNumbersContiguous() const
{
	return m_outputLineNumberDiscontinuityCount == 0;
}

WorldRuntime::SessionStateOutputSnapshot WorldRuntime::sessionStateOutputSnapshot() const
{
	SessionStateOutputSnapshot snapshot;
	snapshot.lines            = m_lines;
	qint64 excludedLineNumber = m_deferredHiddenLuaContextLineNumber;
	int    hiddenIndex        = deferredHiddenIncomingLineIndex();
	if (m_luaContextLineState == LuaContextLineState::AwaitingReplacement)
	{
		excludedLineNumber = m_luaContextLineNumber;
		hiddenIndex        = m_luaContextLineBufferIndex - 1;
	}
	if (excludedLineNumber <= 0)
		return snapshot;

	snapshot.excludedLineNumber = excludedLineNumber;
	if (hiddenIndex >= 0 && hiddenIndex < snapshot.lines.size() &&
	    snapshot.lines.at(hiddenIndex).lineNumber == excludedLineNumber &&
	    (snapshot.lines.at(hiddenIndex).flags & LineHidden) != 0)
	{
		snapshot.excludedLineIndex = hiddenIndex;
	}
	return snapshot;
}

void WorldRuntime::setSessionStateOutputBufferSealed(const bool sealed)
{
	if (QThread::currentThread() != thread())
	{
		qmudInvokeMethodChecked(this, [this, sealed] { setSessionStateOutputBufferSealed(sealed); });
		return;
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::setSessionStateOutputBufferSealed");
	m_sessionStateOutputBufferSealed = sealed;
	if (!sealed)
		removeDeferredHiddenIncomingLine();
}

bool WorldRuntime::isSessionStateOutputBufferSealed() const
{
	return m_sessionStateOutputBufferSealed;
}

void WorldRuntime::replaceOutputLines(const IndexedRingBuffer<LineEntry> &lines)
{
	if (m_sessionStateOutputBufferSealed)
		return;

	invalidateTrackedLuaCallbackOutputAnchors();
	m_lines                              = lines;
	m_outputLineNumberDiscontinuityCount = outputLineNumberDiscontinuityCount(m_lines);
	m_luaCallbackAfterAnchorInsertionCursors.clear();
	m_luaCallbackOutputStreamsByAnchorLineNumber.clear();
	m_luaCallbackOutputAnchorLinesByStream.clear();
	m_luaCallbackOutputIndexOrigin = 0;
	reconcileIncomingLineAfterOutputReplacement();
	invalidateLuaCallbackLineBufferSnapshot();

	qint64 maxLineNumber = 0;
	for (const LineEntry &line : m_lines)
		maxLineNumber = qMax(maxLineNumber, line.lineNumber);
	m_nextLineNumber = qMax<qint64>(1, maxLineNumber + 1);

	static_cast<void>(enforceOutputLineLimit());
	invalidateLuaCallbackLineBufferSnapshot();
	rebuildOutputPresentationViews();
}

void WorldRuntime::replaceOutputLines(const QVector<LineEntry> &lines)
{
	replaceOutputLines(IndexedRingBuffer<LineEntry>(lines));
}

void WorldRuntime::finalizePendingInputLineHardReturn()
{
	if (m_sessionStateOutputBufferSealed)
		return;

	if (m_lines.isEmpty())
		return;

	LineEntry &last = m_lines.last();
	if (last.hardReturn)
		return;
	if ((last.flags & LineInput) == 0)
		return;

	last.hardReturn = true;
	invalidateLuaCallbackLineBufferSnapshot();
}

void WorldRuntime::finalizeOpenOutputLineHardReturn()
{
	if (m_sessionStateOutputBufferSealed || m_lines.isEmpty())
		return;

	LineEntry &last = m_lines.last();
	if (last.hardReturn || last.text.isEmpty())
		return;

	const QString completedLine  = openOutputTextBeforeIndex(safeQSizeToInt(m_lines.size()));
	const int     completedFlags = last.flags;
	last.hardReturn              = true;
	invalidateLuaCallbackLineBufferSnapshot();
	notifyOutputViewLineChanged(safeQSizeToInt(m_lines.size()) - 1);
	if ((completedFlags & LineHorizontalRule) == 0)
	{
		const int type = (completedFlags & LineNote) != 0 ? 1 : ((completedFlags & LineInput) != 0 ? 2 : 0);
		firePluginScreendraw(type, (completedFlags & LineLog) != 0 ? 1 : 0, completedLine);
	}
}

void WorldRuntime::clearLastLineHardReturn()
{
	if (m_sessionStateOutputBufferSealed)
		return;

	if (m_lines.isEmpty())
		return;

	LineEntry &last = m_lines.last();
	if (!last.hardReturn)
		return;

	last.hardReturn = false;
	invalidateLuaCallbackLineBufferSnapshot();
}

void WorldRuntime::beginIncomingLineLuaContext(const QString &text, int flags,
                                               const QVector<StyleSpan> &spans, bool hardReturn)
{
	m_luaPendingContextLineEntry.text       = text;
	m_luaPendingContextLineEntry.flags      = flags;
	m_luaPendingContextLineEntry.hardReturn = hardReturn;
	m_luaPendingContextLineEntry.spans      = spans;
	m_luaPendingContextLineEntry.time       = QDateTime::currentDateTimeUtc();
	m_luaPendingContextLineEntry.lineNumber = m_nextLineNumber;
	m_luaContextLineNumber                  = m_nextLineNumber;
	if (m_lineTimer.isValid())
	{
		m_luaPendingContextLineEntry.ticks   = static_cast<double>(m_lineTimer.nsecsElapsed()) / 1000000000.0;
		m_luaPendingContextLineEntry.elapsed = m_luaPendingContextLineEntry.ticks;
	}
	else
	{
		const double fallback =
		    (m_worldStartTime.isValid() && m_luaPendingContextLineEntry.time.isValid())
		        ? static_cast<double>(m_worldStartTime.msecsTo(m_luaPendingContextLineEntry.time)) / 1000.0
		        : 0.0;
		m_luaPendingContextLineEntry.ticks   = fallback;
		m_luaPendingContextLineEntry.elapsed = fallback;
	}
	m_luaContextLineState       = LuaContextLineState::Pending;
	m_luaContextLineBufferIndex = safeQSizeToInt(m_lines.size() + 1);
	invalidateLuaCallbackLineBufferSnapshot();
}

bool WorldRuntime::reserveIncomingLineLuaContextInBuffer()
{
	if (m_sessionStateOutputBufferSealed)
		return false;

	if (m_luaContextLineState != LuaContextLineState::Pending &&
	    m_luaContextLineState != LuaContextLineState::Buffered)
		return false;
	if (m_luaContextLineState == LuaContextLineState::Buffered)
		return luaContextLinePresentInBuffer();

	LineEntry entry = m_luaPendingContextLineEntry;
	if (entry.lineNumber <= 0)
		entry.lineNumber = m_nextLineNumber;
	if (entry.lineNumber >= m_nextLineNumber)
		m_nextLineNumber = entry.lineNumber + 1;
	const qint64 entryLineNumber = entry.lineNumber;
	appendOutputLine(std::move(entry));
	m_luaContextLineState        = LuaContextLineState::Buffered;
	m_luaContextLineBufferIndex  = safeQSizeToInt(m_lines.size());
	m_luaContextLineNumber       = entryLineNumber;
	m_luaPendingContextLineEntry = {};
	const int removedHeadCount   = enforceOutputLineLimit();
	invalidateLuaCallbackLineBufferSnapshot();
	if (!m_lines.isEmpty())
		notifyOutputViewLineAppended(removedHeadCount);
	return true;
}

bool WorldRuntime::updateBufferedIncomingLineLuaContext(const QString &text, int flags,
                                                        const QVector<StyleSpan> &spans, bool hardReturn)
{
	if (m_sessionStateOutputBufferSealed)
		return false;

	if (!luaContextLinePresentInBuffer())
		return false;

	LineEntry &entry             = m_lines[m_luaContextLineBufferIndex - 1];
	const int  entryIndex        = m_luaContextLineBufferIndex - 1;
	const bool visibilityChanged = ((entry.flags ^ flags) & LineHidden) != 0;
	const bool hardReturnChanged = entry.hardReturn != hardReturn;
	entry.text                   = text;
	entry.flags                  = flags;
	entry.spans                  = spans;
	entry.hardReturn             = hardReturn;
	if (m_luaContextLineState == LuaContextLineState::AwaitingReplacement && (entry.flags & LineHidden) == 0)
	{
		m_luaContextLineState = LuaContextLineState::Buffered;
	}
	refreshTrackedLuaCallbackOutputAnchorsForLine(m_luaContextLineNumber);
	invalidateLuaCallbackLineBufferSnapshot();
	if (visibilityChanged || hardReturnChanged)
		notifyOutputViewRangeChanged(entryIndex, entryIndex + 1);
	else
		notifyOutputViewLineChanged(entryIndex);
	return true;
}

bool WorldRuntime::removeBufferedIncomingLineLuaContext()
{
	if (m_sessionStateOutputBufferSealed)
		return false;

	if (!luaContextLinePresentInBuffer())
		return false;

	const int removedIndex      = m_luaContextLineBufferIndex - 1;
	const int removedCount      = removeOutputLineRange(removedIndex, 1);
	const int firstChangedIndex = qMax(0, qMin(removedIndex, safeQSizeToInt(m_lines.size()) - 1));
	notifyOutputViewRangeChanged(firstChangedIndex, removedIndex, {removedIndex, removedCount, 0},
	                             removedIndex == 0 ? removedCount : 0);
	return true;
}

bool WorldRuntime::hideBufferedIncomingLineLuaContextForReplacement()
{
	if (m_sessionStateOutputBufferSealed)
		return false;

	if (!luaContextLinePresentInBuffer())
		return false;

	LineEntry &entry = m_lines[m_luaContextLineBufferIndex - 1];
	entry.flags |= LineHidden;
	m_luaContextLineState = LuaContextLineState::AwaitingReplacement;
	refreshTrackedLuaCallbackOutputAnchorsForLine(m_luaContextLineNumber);
	invalidateLuaCallbackLineBufferSnapshot();
	notifyOutputViewRangeChanged(m_luaContextLineBufferIndex - 1, m_luaContextLineBufferIndex);
	return true;
}

qint64 WorldRuntime::incomingLineLuaContextAbsoluteNumber() const
{
	if (m_luaContextLineState == LuaContextLineState::Inactive)
		return 0;
	if (m_luaContextLineNumber > 0)
		return m_luaContextLineNumber;
	return m_nextLineNumber;
}

bool WorldRuntime::removeHiddenLuaContextLineByAbsoluteNumber(const qint64 absoluteLineNumber)
{
	if (m_sessionStateOutputBufferSealed)
		return false;

	if (absoluteLineNumber <= 0)
		return false;
	for (int i = 0; i < m_lines.size(); ++i)
	{
		if (m_lines.at(i).lineNumber != absoluteLineNumber)
			continue;
		if ((m_lines.at(i).flags & LineHidden) == 0)
			return false;
		const int removedCount      = removeOutputLineRange(i, 1);
		const int firstChangedIndex = qMax(0, qMin(i, safeQSizeToInt(m_lines.size()) - 1));
		notifyOutputViewRangeChanged(firstChangedIndex, i, {i, removedCount, 0}, i == 0 ? removedCount : 0);
		return true;
	}
	return false;
}

void WorldRuntime::notifyOutputViewLineChanged(const int runtimeLineIndex)
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
		return;
	if (runtimeLineIndex >= 0)
	{
		if (m_outputViewMutationBatchDepth > 0)
		{
			if (m_outputViewRangeChangedPending)
			{
				if (m_outputViewFirstChangedIndex < 0)
					m_outputViewFirstChangedIndex = runtimeLineIndex;
				else
					m_outputViewFirstChangedIndex = qMin(m_outputViewFirstChangedIndex, runtimeLineIndex);
				if (m_outputViewLastChangedIndexExclusive >= 0)
				{
					m_outputViewLastChangedIndexExclusive =
					    qMax(m_outputViewLastChangedIndexExclusive, runtimeLineIndex + 1);
				}
				return;
			}
			if (m_outputViewLineChangedPending && m_outputViewLineChangedIndex >= 0 &&
			    m_outputViewLineChangedIndex != runtimeLineIndex)
			{
				m_outputViewRangeChangedPending = true;
				m_outputViewFirstChangedIndex   = qMin(m_outputViewLineChangedIndex, runtimeLineIndex);
				m_outputViewLastChangedIndexExclusive =
				    qMax(m_outputViewLineChangedIndex, runtimeLineIndex) + 1;
				m_outputViewLineChangedPending = false;
				m_outputViewLineChangedIndex   = -1;
				return;
			}
			m_outputViewLineChangedPending = true;
			m_outputViewLineChangedIndex   = runtimeLineIndex;
			return;
		}
		for (WorldView *view : views)
			view->notifyRuntimeOutputLineChanged(runtimeLineIndex);
		return;
	}
	if (m_outputViewMutationBatchDepth > 0)
	{
		m_outputViewLineChangedPending = true;
		m_outputViewLineChangedIndex   = -1;
		return;
	}
	for (WorldView *view : views)
		view->notifyRuntimeOutputLineChanged();
}

bool WorldRuntime::transformOutputBufferRange(int &firstIndex, int &lastIndexExclusive,
                                              const std::span<const OutputBufferEdit> structuralEdits)
{
	if (firstIndex < 0 || lastIndexExclusive < firstIndex)
		return false;

	qint64 mappedFirst = firstIndex;
	qint64 mappedLast  = lastIndexExclusive;
	for (const OutputBufferEdit &edit : structuralEdits)
	{
		if (edit.index < 0 || edit.removedCount < 0 || edit.insertedCount < 0)
			return false;
		const qint64 editFirst = edit.index;
		const qint64 editLast  = editFirst + static_cast<qint64>(edit.removedCount);
		const qint64 delta     = static_cast<qint64>(edit.insertedCount) - edit.removedCount;

		if (mappedFirst == mappedLast)
		{
			if (mappedFirst > editFirst)
			{
				if (mappedFirst >= editLast)
					mappedFirst += delta;
				else
					mappedFirst = editFirst;
			}
			mappedLast = mappedFirst;
		}
		else
		{
			if (mappedFirst >= editLast)
				mappedFirst += delta;
			else if (mappedFirst >= editFirst)
				mappedFirst = editFirst;

			if (mappedLast > editFirst)
			{
				if (mappedLast >= editLast)
					mappedLast += delta;
				else
					mappedLast = editFirst + edit.insertedCount;
			}
		}

		if (mappedFirst < 0 || mappedLast < mappedFirst || mappedLast > std::numeric_limits<int>::max())
		{
			return false;
		}
	}

	firstIndex         = static_cast<int>(mappedFirst);
	lastIndexExclusive = static_cast<int>(mappedLast);
	return true;
}

void WorldRuntime::transformPendingOutputViewRanges(const std::span<const OutputBufferEdit> structuralEdits)
{
	if (structuralEdits.empty())
		return;

	if (m_outputViewRangeChangedPending && m_outputViewFirstChangedIndex >= 0)
	{
		if (m_outputViewLastChangedIndexExclusive < m_outputViewFirstChangedIndex ||
		    !transformOutputBufferRange(m_outputViewFirstChangedIndex, m_outputViewLastChangedIndexExclusive,
		                                structuralEdits))
		{
			m_outputViewFirstChangedIndex         = 0;
			m_outputViewLastChangedIndexExclusive = -1;
		}
	}
	else if (m_outputViewLineChangedPending && m_outputViewLineChangedIndex >= 0)
	{
		int transformedFirst = m_outputViewLineChangedIndex;
		int transformedLast  = transformedFirst + 1;
		if (!transformOutputBufferRange(transformedFirst, transformedLast, structuralEdits))
		{
			m_outputViewRangeChangedPending       = true;
			m_outputViewFirstChangedIndex         = 0;
			m_outputViewLastChangedIndexExclusive = -1;
			m_outputViewLineChangedPending        = false;
			m_outputViewLineChangedIndex          = -1;
		}
		else if (transformedFirst == transformedLast)
		{
			m_outputViewLineChangedPending = false;
			m_outputViewLineChangedIndex   = -1;
		}
		else if (transformedLast == transformedFirst + 1)
		{
			m_outputViewLineChangedIndex = transformedFirst;
		}
		else
		{
			m_outputViewRangeChangedPending       = true;
			m_outputViewFirstChangedIndex         = transformedFirst;
			m_outputViewLastChangedIndexExclusive = transformedLast;
			m_outputViewLineChangedPending        = false;
			m_outputViewLineChangedIndex          = -1;
		}
	}

	if (m_outputViewTailAppendPending && m_outputViewFirstAppendedIndex >= 0)
	{
		if (m_outputViewLastAppendedIndexExclusive < m_outputViewFirstAppendedIndex ||
		    !transformOutputBufferRange(m_outputViewFirstAppendedIndex,
		                                m_outputViewLastAppendedIndexExclusive, structuralEdits))
		{
			m_outputViewFirstAppendedIndex         = 0;
			m_outputViewLastAppendedIndexExclusive = -1;
		}
		else if (m_outputViewFirstAppendedIndex == m_outputViewLastAppendedIndexExclusive)
		{
			m_outputViewTailAppendPending          = false;
			m_outputViewFirstAppendedIndex         = -1;
			m_outputViewLastAppendedIndexExclusive = -1;
		}
	}

	m_outputViewStructuralEditsPending.reserve(m_outputViewStructuralEditsPending.size() +
	                                           std::ssize(structuralEdits));
	for (const OutputBufferEdit &edit : structuralEdits)
		m_outputViewStructuralEditsPending.push_back(edit);
}

void WorldRuntime::notifyOutputViewLineAppended(const int removedHeadCount)
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
		return;
	const int boundedRemovedHeadCount   = qMax(0, removedHeadCount);
	const int postMutationSize          = safeQSizeToInt(m_lines.size());
	const int appendIndexBeforeMutation = postMutationSize + boundedRemovedHeadCount - 1;
	std::array<OutputBufferEdit, 2> structuralEdits{};
	int                             structuralEditCount = 0;
	if (appendIndexBeforeMutation >= 0)
		structuralEdits[structuralEditCount++] = {appendIndexBeforeMutation, 0, 1};
	if (boundedRemovedHeadCount > 0)
		structuralEdits[structuralEditCount++] = {0, boundedRemovedHeadCount, 0};
	const std::span<const OutputBufferEdit> editSpan(structuralEdits.data(),
	                                                 static_cast<std::size_t>(structuralEditCount));
	if (m_outputViewMutationBatchDepth > 0)
	{
		transformPendingOutputViewRanges(editSpan);
		const int firstAppendedIndex         = postMutationSize - 1;
		const int lastAppendedIndexExclusive = postMutationSize;
		if (!m_outputViewTailAppendPending)
		{
			m_outputViewFirstAppendedIndex         = firstAppendedIndex;
			m_outputViewLastAppendedIndexExclusive = lastAppendedIndexExclusive;
		}
		else if (m_outputViewLastAppendedIndexExclusive >= m_outputViewFirstAppendedIndex)
		{
			m_outputViewFirstAppendedIndex = qMin(m_outputViewFirstAppendedIndex, firstAppendedIndex);
			m_outputViewLastAppendedIndexExclusive =
			    qMax(m_outputViewLastAppendedIndexExclusive, lastAppendedIndexExclusive);
		}
		m_outputViewTailAppendPending = true;
		return;
	}
	const int previousHeadRemovalCount = previousOutputHeadRemovalCount(
	    outputBufferLineCountBeforeEdits(postMutationSize, editSpan), editSpan);
	for (WorldView *view : views)
		view->notifyRuntimeOutputLineAppended(postMutationSize - 1, postMutationSize, editSpan,
		                                      previousHeadRemovalCount);
}

void WorldRuntime::notifyOutputViewLinesAppended(const int              firstAppendedIndex,
                                                 const int              lastAppendedIndexExclusive,
                                                 const OutputBufferEdit structuralEdit,
                                                 const int              removedHeadCount)
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
		return;
	Q_ASSERT(firstAppendedIndex >= 0 && lastAppendedIndexExclusive > firstAppendedIndex);
	if (firstAppendedIndex < 0 || lastAppendedIndexExclusive <= firstAppendedIndex)
		return;

	const int                       boundedRemovedHeadCount = qMax(0, removedHeadCount);
	std::array<OutputBufferEdit, 2> structuralEdits{};
	int                             structuralEditCount = 0;
	if (structuralEdit.index >= 0)
		structuralEdits[structuralEditCount++] = structuralEdit;
	if (boundedRemovedHeadCount > 0)
		structuralEdits[structuralEditCount++] = {0, boundedRemovedHeadCount, 0};
	const std::span<const OutputBufferEdit> editSpan(structuralEdits.data(),
	                                                 static_cast<std::size_t>(structuralEditCount));

	if (m_outputViewMutationBatchDepth > 0)
	{
		transformPendingOutputViewRanges(editSpan);
		if (!m_outputViewTailAppendPending)
		{
			m_outputViewFirstAppendedIndex         = firstAppendedIndex;
			m_outputViewLastAppendedIndexExclusive = lastAppendedIndexExclusive;
		}
		else if (m_outputViewLastAppendedIndexExclusive >= m_outputViewFirstAppendedIndex)
		{
			m_outputViewFirstAppendedIndex = qMin(m_outputViewFirstAppendedIndex, firstAppendedIndex);
			m_outputViewLastAppendedIndexExclusive =
			    qMax(m_outputViewLastAppendedIndexExclusive, lastAppendedIndexExclusive);
		}
		m_outputViewTailAppendPending = true;
		return;
	}

	const int previousHeadRemovalCount = previousOutputHeadRemovalCount(
	    outputBufferLineCountBeforeEdits(safeQSizeToInt(m_lines.size()), editSpan), editSpan);
	for (WorldView *view : views)
		view->notifyRuntimeOutputLineAppended(firstAppendedIndex, lastAppendedIndexExclusive, editSpan,
		                                      previousHeadRemovalCount);
}

void WorldRuntime::notifyOutputViewTailRangeChangedAndLinesAppended(
    const int firstChangedIndex, const int lastChangedIndexExclusive, const int firstAppendedIndex,
    const int lastAppendedIndexExclusive, const OutputBufferEdit structuralEdit, const int removedHeadCount)
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
		return;
	Q_ASSERT(firstChangedIndex >= 0 && lastChangedIndexExclusive > firstChangedIndex);
	Q_ASSERT(firstAppendedIndex >= 0 && lastAppendedIndexExclusive > firstAppendedIndex);
	if (firstChangedIndex < 0 || lastChangedIndexExclusive <= firstChangedIndex || firstAppendedIndex < 0 ||
	    lastAppendedIndexExclusive <= firstAppendedIndex)
	{
		return;
	}

	const int                       boundedRemovedHeadCount = qMax(0, removedHeadCount);
	std::array<OutputBufferEdit, 2> structuralEdits{};
	int                             structuralEditCount = 0;
	if (structuralEdit.index >= 0)
		structuralEdits[structuralEditCount++] = structuralEdit;
	if (boundedRemovedHeadCount > 0)
		structuralEdits[structuralEditCount++] = {0, boundedRemovedHeadCount, 0};
	const std::span<const OutputBufferEdit> editSpan(structuralEdits.data(),
	                                                 static_cast<std::size_t>(structuralEditCount));

	if (m_outputViewMutationBatchDepth > 0)
	{
		transformPendingOutputViewRanges(editSpan);
		if (m_outputViewRangeChangedPending)
		{
			m_outputViewFirstChangedIndex = qMin(m_outputViewFirstChangedIndex, firstChangedIndex);
			if (m_outputViewLastChangedIndexExclusive >= 0)
			{
				m_outputViewLastChangedIndexExclusive =
				    qMax(m_outputViewLastChangedIndexExclusive, lastChangedIndexExclusive);
			}
		}
		else
		{
			int mergedFirstChangedIndex         = firstChangedIndex;
			int mergedLastChangedIndexExclusive = lastChangedIndexExclusive;
			if (m_outputViewLineChangedPending && m_outputViewLineChangedIndex >= 0)
			{
				mergedFirstChangedIndex = qMin(mergedFirstChangedIndex, m_outputViewLineChangedIndex);
				mergedLastChangedIndexExclusive =
				    qMax(mergedLastChangedIndexExclusive, m_outputViewLineChangedIndex + 1);
			}
			m_outputViewFirstChangedIndex         = mergedFirstChangedIndex;
			m_outputViewLastChangedIndexExclusive = mergedLastChangedIndexExclusive;
		}
		m_outputViewRangeChangedPending = true;
		m_outputViewLineChangedPending  = false;
		m_outputViewLineChangedIndex    = -1;

		if (!m_outputViewTailAppendPending)
		{
			m_outputViewFirstAppendedIndex         = firstAppendedIndex;
			m_outputViewLastAppendedIndexExclusive = lastAppendedIndexExclusive;
		}
		else if (m_outputViewLastAppendedIndexExclusive >= m_outputViewFirstAppendedIndex)
		{
			m_outputViewFirstAppendedIndex = qMin(m_outputViewFirstAppendedIndex, firstAppendedIndex);
			m_outputViewLastAppendedIndexExclusive =
			    qMax(m_outputViewLastAppendedIndexExclusive, lastAppendedIndexExclusive);
		}
		m_outputViewTailAppendPending = true;
		return;
	}

	const int previousHeadRemovalCount = previousOutputHeadRemovalCount(
	    outputBufferLineCountBeforeEdits(safeQSizeToInt(m_lines.size()), editSpan), editSpan);
	for (WorldView *view : views)
	{
		view->notifyRuntimeOutputRangeChanged(firstChangedIndex, lastChangedIndexExclusive, editSpan,
		                                      previousHeadRemovalCount);
		view->notifyRuntimeOutputLineAppended(firstAppendedIndex, lastAppendedIndexExclusive);
	}
}

void WorldRuntime::notifyOutputViewRangeChanged(const int runtimeLineIndex, const int runtimeLineEndExclusive,
                                                const OutputBufferEdit structuralEdit,
                                                const int              removedHeadCount)
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
		return;
	const int                       boundedRemovedHeadCount = qMax(0, removedHeadCount);
	std::array<OutputBufferEdit, 2> structuralEdits{};
	int                             structuralEditCount = 0;
	if (structuralEdit.index >= 0)
		structuralEdits[structuralEditCount++] = structuralEdit;
	const bool primaryEditIncludesHeadRemoval = structuralEdit.index == 0 &&
	                                            structuralEdit.removedCount == boundedRemovedHeadCount &&
	                                            structuralEdit.insertedCount == 0;
	if (boundedRemovedHeadCount > 0 && !primaryEditIncludesHeadRemoval)
		structuralEdits[structuralEditCount++] = {0, boundedRemovedHeadCount, 0};
	const std::span<const OutputBufferEdit> editSpan(structuralEdits.data(),
	                                                 static_cast<std::size_t>(structuralEditCount));
	if (m_outputViewMutationBatchDepth > 0)
	{
		transformPendingOutputViewRanges(editSpan);
		int firstChangedIndex = qMax(0, runtimeLineIndex);
		int lastChangedIndexExclusive =
		    runtimeLineEndExclusive >= runtimeLineIndex ? runtimeLineEndExclusive : -1;
		if (m_outputViewRangeChangedPending)
		{
			m_outputViewFirstChangedIndex = qMin(m_outputViewFirstChangedIndex, firstChangedIndex);
			if (m_outputViewLastChangedIndexExclusive < 0 || lastChangedIndexExclusive < 0)
				m_outputViewLastChangedIndexExclusive = -1;
			else
				m_outputViewLastChangedIndexExclusive =
				    qMax(m_outputViewLastChangedIndexExclusive, lastChangedIndexExclusive);
		}
		else
		{
			if (m_outputViewLineChangedPending && m_outputViewLineChangedIndex >= 0)
			{
				firstChangedIndex = qMin(firstChangedIndex, m_outputViewLineChangedIndex);
				if (lastChangedIndexExclusive >= 0)
					lastChangedIndexExclusive =
					    qMax(lastChangedIndexExclusive, m_outputViewLineChangedIndex + 1);
			}
			m_outputViewFirstChangedIndex         = firstChangedIndex;
			m_outputViewLastChangedIndexExclusive = lastChangedIndexExclusive;
		}
		m_outputViewRangeChangedPending = true;
		m_outputViewLineChangedPending  = false;
		m_outputViewLineChangedIndex    = -1;
		return;
	}
	const int previousHeadRemovalCount = previousOutputHeadRemovalCount(
	    outputBufferLineCountBeforeEdits(safeQSizeToInt(m_lines.size()), editSpan), editSpan);
	for (WorldView *view : views)
		view->notifyRuntimeOutputRangeChanged(runtimeLineIndex, runtimeLineEndExclusive, editSpan,
		                                      previousHeadRemovalCount);
}

void WorldRuntime::rebuildOutputPresentationViews() const
{
	for (WorldView *view : presentationViews())
		view->restoreOutputFromPersistedLines(m_lines);
}

void WorldRuntime::clearOutputPresentationViews() const
{
	for (WorldView *view : presentationViews())
		view->clearOutputBuffer();
}

void WorldRuntime::resetPendingOutputViewMutationNotifications()
{
	m_outputViewLineChangedPending         = false;
	m_outputViewLineChangedIndex           = -1;
	m_outputViewRangeChangedPending        = false;
	m_outputViewFirstChangedIndex          = -1;
	m_outputViewLastChangedIndexExclusive  = -1;
	m_outputViewTailAppendPending          = false;
	m_outputViewFirstAppendedIndex         = -1;
	m_outputViewLastAppendedIndexExclusive = -1;
	m_outputViewStructuralEditsPending.clear();
}

void WorldRuntime::flushOutputViewMutationBatch()
{
	const QVector<WorldView *> views = presentationViews();
	if (views.isEmpty())
	{
		resetPendingOutputViewMutationNotifications();
		m_outputViewMutationBatchInitialLineCount = safeQSizeToInt(m_lines.size());
		return;
	}
	bool                      rangeChanged               = m_outputViewRangeChangedPending;
	const int                 firstChangedIndex          = m_outputViewFirstChangedIndex;
	const int                 lastChangedIndexExclusive  = m_outputViewLastChangedIndexExclusive;
	bool                      changed                    = m_outputViewLineChangedPending;
	const int                 changedIndex               = m_outputViewLineChangedIndex;
	const bool                tailAppended               = m_outputViewTailAppendPending;
	const int                 firstAppendedIndex         = m_outputViewFirstAppendedIndex;
	const int                 lastAppendedIndexExclusive = m_outputViewLastAppendedIndexExclusive;
	QVector<OutputBufferEdit> structuralEdits            = std::move(m_outputViewStructuralEditsPending);
	resetPendingOutputViewMutationNotifications();
	const std::span<const OutputBufferEdit> editSpan(structuralEdits.constData(),
	                                                 static_cast<std::size_t>(structuralEdits.size()));
	const int                               initialLineCount = m_outputViewMutationBatchInitialLineCount;
	const int previousHeadRemovalCount        = previousOutputHeadRemovalCount(initialLineCount, editSpan);
	m_outputViewMutationBatchInitialLineCount = safeQSizeToInt(m_lines.size());
	const bool exactAppendRange =
	    tailAppended && firstAppendedIndex >= 0 && lastAppendedIndexExclusive > firstAppendedIndex;
	bool hasNonTailStructuralEdit = false;
	int  lineCountBeforeEdit      = initialLineCount;
	for (const OutputBufferEdit &edit : editSpan)
	{
		if (edit.index < lineCountBeforeEdit && edit.index + edit.removedCount < lineCountBeforeEdit)
			hasNonTailStructuralEdit = true;
		lineCountBeforeEdit += edit.insertedCount - edit.removedCount;
	}
	if (!hasNonTailStructuralEdit && rangeChanged && exactAppendRange &&
	    firstChangedIndex >= firstAppendedIndex && lastChangedIndexExclusive >= firstChangedIndex &&
	    lastChangedIndexExclusive <= lastAppendedIndexExclusive)
	{
		rangeChanged = false;
	}
	if (!hasNonTailStructuralEdit && changed && exactAppendRange && changedIndex >= firstAppendedIndex &&
	    changedIndex < lastAppendedIndexExclusive)
	{
		changed = false;
	}
	if (rangeChanged)
	{
		const int boundedFirstChangedIndex = qMax(0, firstChangedIndex);
		const int boundedLastChangedIndexExclusive =
		    firstChangedIndex < 0 || lastChangedIndexExclusive < 0 ? -1 : lastChangedIndexExclusive;
		for (WorldView *view : views)
		{
			view->notifyRuntimeOutputRangeChanged(boundedFirstChangedIndex, boundedLastChangedIndexExclusive,
			                                      editSpan, previousHeadRemovalCount);
			if (tailAppended)
				view->notifyRuntimeOutputLineAppended(firstAppendedIndex, lastAppendedIndexExclusive);
		}
		return;
	}
	if (changed)
	{
		for (WorldView *view : views)
		{
			if (tailAppended)
			{
				const int firstChanged = qMax(0, changedIndex);
				view->notifyRuntimeOutputRangeChanged(firstChanged, changedIndex >= 0 ? firstChanged + 1 : -1,
				                                      editSpan, previousHeadRemovalCount);
				view->notifyRuntimeOutputLineAppended(firstAppendedIndex, lastAppendedIndexExclusive);
			}
			else if (changedIndex >= 0)
				view->notifyRuntimeOutputLineChanged(changedIndex);
			else
				view->notifyRuntimeOutputLineChanged();
		}
		return;
	}
	if (tailAppended)
	{
		for (WorldView *view : views)
			view->notifyRuntimeOutputLineAppended(firstAppendedIndex, lastAppendedIndexExclusive, editSpan,
			                                      previousHeadRemovalCount);
	}
}

void WorldRuntime::publishIncomingStyledLinePartial(const QString &line, const QVector<StyleSpan> &spans)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::publishIncomingStyledLinePartial");
	if (m_incomingStreamPresentationBatchDepth == 0 &&
	    (m_outputViewLineChangedPending || m_outputViewRangeChangedPending || m_outputViewTailAppendPending))
		flushOutputViewMutationBatch();
	emit incomingStyledLinePartialReceived(line, spans);
}

void WorldRuntime::setIncomingPartialLineRevision(const quint64 revision)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::setIncomingPartialLineRevision");
	if (m_incomingPartialLineRevision == revision)
		return;
	invalidatePendingPartialLineDispatch();
	m_incomingPartialLineRevision = revision;
}

void WorldRuntime::invalidatePendingPartialLineDispatch()
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::invalidatePendingPartialLineDispatch");
	if (!m_pendingPartialLineDispatch)
		return;
	const std::shared_ptr<PendingPartialLineDispatchState> state =
	    std::exchange(m_pendingPartialLineDispatch, {});
	if (state->started || !state->queueHandle || !state->queueHandle->owner)
		return;
	PluginCallbackLaneQueue *const           owner     = state->queueHandle->owner;
	const bool                               wasStaged = owner->isStagedCausal();
	std::optional<PluginCallbackLaneCommand> removed   = owner->remove(state->queueHandle);
	if (!removed)
		return;
	if (wasStaged)
	{
		Q_ASSERT(m_stagedPluginCallbackCausalCommandCount > 0);
		if (m_stagedPluginCallbackCausalCommandCount > 0)
			--m_stagedPluginCallbackCausalCommandCount;
	}
	if (removed->kind == PluginCallbackLaneCommand::Kind::CallbackDispatch)
		finishDiscardedPluginCallbackDispatchCommand(std::move(removed->callback));
}

void WorldRuntime::beginOutputViewMutationBatch()
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::beginOutputViewMutationBatch");
	if (m_outputViewMutationBatchDepth == 0)
	{
		m_outputViewMutationBatchInitialLineCount = safeQSizeToInt(m_lines.size());
		m_outputViewMutationBatchViews.clear();
		for (WorldView *view : presentationViews())
		{
			m_outputViewMutationBatchViews.push_back(view);
			view->beginRuntimeOutputMutationBatch(m_drawOutputWindowMutationReplayDepth > 0);
		}
	}
	++m_outputViewMutationBatchDepth;
}

void WorldRuntime::endOutputViewMutationBatch()
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::endOutputViewMutationBatch");
	if (m_outputViewMutationBatchDepth <= 0)
		return;
	--m_outputViewMutationBatchDepth;
	if (m_outputViewMutationBatchDepth > 0)
		return;
	const QVector<QPointer<WorldView>> batchViews = std::move(m_outputViewMutationBatchViews);
	m_outputViewMutationBatchViews.clear();
	flushOutputViewMutationBatch();
	for (const QPointer<WorldView> &view : batchViews)
	{
		if (view)
			view->endRuntimeOutputMutationBatch();
	}
}

bool WorldRuntime::writeLuaCallbackOutputAtLineAnchor(
    const qint64 anchorLineNumber, const int anchorBufferIndex, const int anchorRelativeOffset,
    const bool replaceAnchor, const QString &text, int flags, const QVector<StyleSpan> &spans,
    const bool hardReturn, const quint64 outputStreamId,
    const std::shared_ptr<LuaCallbackOutputAnchorState> &anchorState, int *const resolvedAnchorBufferIndex)
{
	if (resolvedAnchorBufferIndex)
		*resolvedAnchorBufferIndex = 0;
	if (text.isEmpty() && !hardReturn)
		return false;

	const auto failWrite = [this, outputStreamId, anchorLineNumber, &anchorState]
	{
		invalidateLuaCallbackOutputAnchor(outputStreamId, anchorLineNumber, anchorState);
		return false;
	};
	if (m_sessionStateOutputBufferSealed)
		return failWrite();

	if (anchorLineNumber <= 0 || anchorBufferIndex <= 0 || anchorRelativeOffset < 0)
		return failWrite();
	LuaCallbackOutputPosition outputPosition;
	if (!resolveLuaCallbackOutputPosition(anchorLineNumber, anchorBufferIndex, anchorRelativeOffset,
	                                      replaceAnchor, outputStreamId, anchorState, outputPosition))
		return failWrite();
	const int                   insertionIndex  = outputPosition.insertionIndex;
	const QString               openLinePrefix  = openOutputTextBeforeIndex(insertionIndex);
	const QStringList           screenDrawLines = completedScreenDrawLines(text, hardReturn, openLinePrefix);

	QString                     displayText          = text;
	QVector<StyleSpan>          displaySpans         = spans;
	const bool                  note                 = (flags & LineNote) != 0;
	const bool                  localContent         = note || (flags & LineInput) != 0;
	const bool                  serverSideWrapActive = isConnected() && m_telnet.isNawsNegotiated();
	const FixedColumnWrapConfig wrapConfig =
	    (!localContent && serverSideWrapActive)
	        ? FixedColumnWrapConfig{}
	        : localOutputWrapConfig(m_worldAttributes, serverSideWrapActive, m_telnet.windowColumns());
	if (wrapConfig.enabled && !displayText.isEmpty())
	{
		if (displaySpans.isEmpty())
			wrapPlainLineForColumn(displayText, wrapConfig.wrapColumn, wrapConfig.indentParas,
			                       openOutputPrefixColumnsBeforeIndex(insertionIndex),
			                       openLinePrefix.endsWith(QLatin1Char(' ')));
		else
			wrapStyledLineForColumn(displayText, displaySpans, wrapConfig.wrapColumn, wrapConfig.indentParas,
			                        openOutputPrefixColumnsBeforeIndex(insertionIndex),
			                        openLinePrefix.endsWith(QLatin1Char(' ')));
	}
	const QVector<OutputLineSegment> segments =
	    splitOutputTextAtLineBreaks(displayText, displaySpans, hardReturn);
	if (segments.isEmpty())
		return false;
	QVector<LineEntry> preparedSegments;
	preparedSegments.reserve(segments.size());
	for (const OutputLineSegment &segment : segments)
	{
		LineEntry entry;
		entry.text       = segment.text;
		entry.spans      = segment.spans;
		entry.hardReturn = segment.hardReturn;
		preparedSegments.push_back(std::move(entry));
	}
	const bool written = writeLuaCallbackOutputSegmentsAtLineAnchor(
	    anchorLineNumber, anchorRelativeOffset, replaceAnchor, outputPosition, preparedSegments, flags,
	    outputStreamId, screenDrawLines, anchorState, resolvedAnchorBufferIndex);
	if (!written)
		return failWrite();
	return true;
}

bool WorldRuntime::resolveLuaCallbackOutputPosition(
    const qint64 anchorLineNumber, const int anchorBufferIndex, const int anchorRelativeOffset,
    const bool replaceAnchor, const quint64 outputStreamId,
    const std::shared_ptr<LuaCallbackOutputAnchorState> &anchorState, LuaCallbackOutputPosition &position)
{
	position = {};
	if (anchorLineNumber <= 0 || anchorBufferIndex <= 0 || anchorRelativeOffset < 0)
		return false;

	const LuaCallbackOutputCursorKey cursorKey{outputStreamId, anchorLineNumber};
	auto                             cursorIt    = m_luaCallbackAfterAnchorInsertionCursors.find(cursorKey);
	const auto                       cachedIndex = [this](const qint64 position) -> qint64
	{ return position - m_luaCallbackOutputIndexOrigin; };
	const qint64 cachedAnchorIndex   = cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end()
	                                       ? cachedIndex(cursorIt->anchorPosition)
	                                       : -1;
	bool         cachedPositionValid = cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end() &&
	                                   cachedAnchorIndex >= 0 && cachedAnchorIndex < m_lines.size() &&
	                                   m_lines.at(cachedAnchorIndex).lineNumber == anchorLineNumber;
	if (cachedPositionValid && cursorIt->cursorLineNumber > 0)
	{
		const qint64 cachedCursorIndex = cachedIndex(cursorIt->cursorPosition);
		cachedPositionValid = cachedCursorIndex >= cachedAnchorIndex && cachedCursorIndex < m_lines.size() &&
		                      m_lines.at(cachedCursorIndex).lineNumber == cursorIt->cursorLineNumber;
	}

	if (!cachedPositionValid)
	{
		if (cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end())
		{
			Q_ASSERT_X(false, "WorldRuntime::resolveLuaCallbackOutputPosition",
			           "Callback output cursor position was not reconciled by a structural mutation");
			if (cursorIt->trackedAnchorState)
				cursorIt->trackedAnchorState->clearPresentation();
			unindexLuaCallbackOutputCursor(cursorKey);
			m_luaCallbackAfterAnchorInsertionCursors.remove(cursorKey);
			return false;
		}

		int anchorIndex = -1;
		if (m_luaContextLineNumber == anchorLineNumber && luaContextLinePresentInBuffer())
			anchorIndex = m_luaContextLineBufferIndex - 1;
		else
		{
			const LuaContextBufferPresentation presentation = luaContextBufferPresentation();
			anchorIndex = presentation.physicalIndexForBufferIndex(anchorBufferIndex);
		}
		if (anchorIndex < 0 || anchorIndex >= m_lines.size() ||
		    m_lines.at(anchorIndex).lineNumber != anchorLineNumber)
		{
			return false;
		}

		LuaCallbackOutputInsertionCursor cursor;
		cursor.anchorPosition = m_luaCallbackOutputIndexOrigin + anchorIndex;
		cursorIt              = m_luaCallbackAfterAnchorInsertionCursors.insert(cursorKey, cursor);
		indexLuaCallbackOutputCursor(cursorKey);
	}

	position.anchorIndex            = static_cast<int>(cachedIndex(cursorIt->anchorPosition));
	const bool activeIncomingAnchor = anchorLineNumber == m_luaContextLineNumber;
	const std::shared_ptr<LuaCallbackOutputAnchorState> placementState =
	    anchorState ? anchorState : cursorIt->trackedAnchorState;
	const bool followsActiveIncomingTail =
	    !placementState || placementState->placementMode() ==
	                           LuaCallbackOutputAnchorState::PlacementMode::FollowActiveIncomingTail;
	const int outputTailIndex = safeQSizeToInt(m_lines.size());
	// Synchronous incoming-line callbacks append after earlier callback actions at the active tail. An
	// asynchronous stream notification instead keeps the event boundary captured before parsing advanced.
	if (replaceAnchor)
	{
		position.insertionIndex =
		    followsActiveIncomingTail && activeIncomingAnchor && position.anchorIndex + 1 < outputTailIndex
		        ? outputTailIndex
		        : position.anchorIndex;
		return true;
	}

	const int requestedIndex = static_cast<int>(
	    qBound<qint64>(0, static_cast<qint64>(position.anchorIndex) + anchorRelativeOffset, m_lines.size()));
	position.insertionIndex =
	    cursorIt->cursorLineNumber > 0
	        ? qMax(requestedIndex, static_cast<int>(cachedIndex(cursorIt->cursorPosition)) + 1)
	        : requestedIndex;
	if (followsActiveIncomingTail && anchorRelativeOffset > 0 && activeIncomingAnchor)
		position.insertionIndex = outputTailIndex;
	return true;
}

quint64 WorldRuntime::allocateOutputInsertionStreamId()
{
	static std::atomic<quint64> nextId{1};
	quint64                     id = nextId.fetch_add(1, std::memory_order_relaxed);
	while (id == 0)
		id = nextId.fetch_add(1, std::memory_order_relaxed);
	return id;
}

bool WorldRuntime::registerLuaCallbackOutputAnchor(
    const quint64 outputStreamId, const qint64 anchorLineNumber, const int anchorBufferIndex,
    const std::shared_ptr<LuaCallbackOutputAnchorState> &anchorState)
{
	if (outputStreamId == 0 || anchorLineNumber <= 0 || anchorBufferIndex <= 0 || !anchorState)
		return false;
	anchorState->bindHeadRemovalCount(m_luaCallbackOutputHeadRemovalCount);

	int anchorIndex = -1;
	if (m_luaContextLineNumber == anchorLineNumber && luaContextLinePresentInBuffer())
		anchorIndex = m_luaContextLineBufferIndex - 1;
	else
		anchorIndex = luaContextBufferPresentation().physicalIndexForBufferIndex(anchorBufferIndex);
	if (anchorIndex < 0 || anchorIndex >= m_lines.size() ||
	    m_lines.at(anchorIndex).lineNumber != anchorLineNumber)
	{
		return false;
	}

	LuaCallbackOutputInsertionCursor cursor;
	cursor.anchorPosition     = m_luaCallbackOutputIndexOrigin + anchorIndex;
	cursor.trackedAnchorState = anchorState;
	const LuaCallbackOutputCursorKey key{outputStreamId, anchorLineNumber};
	if (const auto existing = m_luaCallbackAfterAnchorInsertionCursors.constFind(key);
	    existing != m_luaCallbackAfterAnchorInsertionCursors.cend())
	{
		if (existing->trackedAnchorState)
			existing->trackedAnchorState->clearPresentation();
		unindexLuaCallbackOutputCursor(key);
	}
	m_luaCallbackAfterAnchorInsertionCursors.insert(key, std::move(cursor));
	indexLuaCallbackOutputCursor(key);
	const auto inserted = m_luaCallbackAfterAnchorInsertionCursors.constFind(key);
	Q_ASSERT(inserted != m_luaCallbackAfterAnchorInsertionCursors.cend());
	refreshTrackedLuaCallbackOutputAnchor(key, *inserted, luaContextBufferPresentation());
	return anchorState->presentation().bufferIndex > 0;
}

void WorldRuntime::invalidateLuaCallbackOutputAnchor(
    const quint64 outputStreamId, const qint64 anchorLineNumber,
    const std::shared_ptr<LuaCallbackOutputAnchorState> &anchorState)
{
	if (anchorState)
		anchorState->clearPresentation();

	const LuaCallbackOutputCursorKey key{outputStreamId, anchorLineNumber};
	auto                             cursorIt = m_luaCallbackAfterAnchorInsertionCursors.find(key);
	if (cursorIt == m_luaCallbackAfterAnchorInsertionCursors.end())
		return;
	if (cursorIt->trackedAnchorState)
		cursorIt->trackedAnchorState->clearPresentation();
	unindexLuaCallbackOutputCursor(key);
	m_luaCallbackAfterAnchorInsertionCursors.erase(cursorIt);
}

void WorldRuntime::indexLuaCallbackOutputCursor(const LuaCallbackOutputCursorKey &key)
{
	QSet<quint64> &streams = m_luaCallbackOutputStreamsByAnchorLineNumber[key.anchorLineNumber];
	Q_ASSERT(!streams.contains(key.outputStreamId));
	streams.insert(key.outputStreamId);
	QSet<qint64> &anchorLines = m_luaCallbackOutputAnchorLinesByStream[key.outputStreamId];
	Q_ASSERT(!anchorLines.contains(key.anchorLineNumber));
	anchorLines.insert(key.anchorLineNumber);
}

void WorldRuntime::unindexLuaCallbackOutputCursor(const LuaCallbackOutputCursorKey &key)
{
	auto streams = m_luaCallbackOutputStreamsByAnchorLineNumber.find(key.anchorLineNumber);
	Q_ASSERT(streams != m_luaCallbackOutputStreamsByAnchorLineNumber.end());
	if (streams != m_luaCallbackOutputStreamsByAnchorLineNumber.end())
	{
		Q_ASSERT(streams->contains(key.outputStreamId));
		streams->remove(key.outputStreamId);
		if (streams->isEmpty())
			m_luaCallbackOutputStreamsByAnchorLineNumber.erase(streams);
	}
	auto anchorLines = m_luaCallbackOutputAnchorLinesByStream.find(key.outputStreamId);
	Q_ASSERT(anchorLines != m_luaCallbackOutputAnchorLinesByStream.end());
	if (anchorLines != m_luaCallbackOutputAnchorLinesByStream.end())
	{
		Q_ASSERT(anchorLines->contains(key.anchorLineNumber));
		anchorLines->remove(key.anchorLineNumber);
		if (anchorLines->isEmpty())
			m_luaCallbackOutputAnchorLinesByStream.erase(anchorLines);
	}
}

void WorldRuntime::refreshTrackedLuaCallbackOutputAnchor(const LuaCallbackOutputCursorKey       &key,
                                                         const LuaCallbackOutputInsertionCursor &cursor,
                                                         const LuaContextBufferPresentation     &presentation)
{
	const std::shared_ptr<LuaCallbackOutputAnchorState> &state = cursor.trackedAnchorState;
	if (!state)
		return;
	const qint64 physicalIndex = cursor.anchorPosition - m_luaCallbackOutputIndexOrigin;
	if (physicalIndex < 0 || physicalIndex >= m_lines.size() ||
	    m_lines.at(physicalIndex).lineNumber != key.anchorLineNumber)
	{
		Q_ASSERT_X(false, "WorldRuntime::refreshTrackedLuaCallbackOutputAnchor",
		           "Callback output anchor position was not reconciled by a structural mutation");
		state->clearPresentation();
		return;
	}
	const LineEntry &entry = m_lines.at(physicalIndex);
	state->storePresentation(presentation.bufferIndexForPhysicalIndex(static_cast<int>(physicalIndex)),
	                         entry.lineNumber == m_luaContextLineNumber, (entry.flags & LineHidden) != 0);
}

void WorldRuntime::refreshTrackedLuaCallbackOutputAnchorsForLine(const qint64 anchorLineNumber)
{
	const auto streams = m_luaCallbackOutputStreamsByAnchorLineNumber.constFind(anchorLineNumber);
	if (streams == m_luaCallbackOutputStreamsByAnchorLineNumber.cend())
		return;
	const LuaContextBufferPresentation presentation = luaContextBufferPresentation();
	for (const quint64 outputStreamId : *streams)
	{
		const LuaCallbackOutputCursorKey key{outputStreamId, anchorLineNumber};
		const auto                       cursor = m_luaCallbackAfterAnchorInsertionCursors.constFind(key);
		Q_ASSERT(cursor != m_luaCallbackAfterAnchorInsertionCursors.cend());
		if (cursor == m_luaCallbackAfterAnchorInsertionCursors.cend())
			continue;
		if (cursor->trackedAnchorState)
			refreshTrackedLuaCallbackOutputAnchor(key, *cursor, presentation);
	}
}

void WorldRuntime::invalidateTrackedLuaCallbackOutputAnchors()
{
	for (const LuaCallbackOutputInsertionCursor &cursor :
	     std::as_const(m_luaCallbackAfterAnchorInsertionCursors))
	{
		if (!cursor.trackedAnchorState)
			continue;
		cursor.trackedAnchorState->clearPresentation();
	}
}

void WorldRuntime::releaseLuaCallbackOutputStream(const quint64 outputStreamId)
{
	if (outputStreamId == 0)
		return;
	const QSet<qint64> anchorLines = m_luaCallbackOutputAnchorLinesByStream.value(outputStreamId);
	for (const qint64 anchorLineNumber : anchorLines)
	{
		const LuaCallbackOutputCursorKey key{outputStreamId, anchorLineNumber};
		auto                             cursor = m_luaCallbackAfterAnchorInsertionCursors.find(key);
		Q_ASSERT(cursor != m_luaCallbackAfterAnchorInsertionCursors.end());
		if (cursor == m_luaCallbackAfterAnchorInsertionCursors.end())
		{
			unindexLuaCallbackOutputCursor(key);
			continue;
		}
		if (cursor->trackedAnchorState)
		{
			quint64 expected = outputStreamId;
			static_cast<void>(cursor->trackedAnchorState->outputStreamId.compare_exchange_strong(
			    expected, 0, std::memory_order_relaxed));
		}
		unindexLuaCallbackOutputCursor(key);
		m_luaCallbackAfterAnchorInsertionCursors.erase(cursor);
	}
}

qsizetype WorldRuntime::luaCallbackOutputCursorCount() const
{
	return m_luaCallbackAfterAnchorInsertionCursors.size();
}

int WorldRuntime::luaCallbackOutputAnchorBufferIndex(const quint64 outputStreamId,
                                                     const qint64  anchorLineNumber) const
{
	const auto cursorIt =
	    m_luaCallbackAfterAnchorInsertionCursors.constFind({outputStreamId, anchorLineNumber});
	if (cursorIt == m_luaCallbackAfterAnchorInsertionCursors.cend())
		return 0;
	const qint64 physicalIndex = cursorIt->anchorPosition - m_luaCallbackOutputIndexOrigin;
	if (physicalIndex < 0 || physicalIndex >= m_lines.size() ||
	    m_lines.at(physicalIndex).lineNumber != anchorLineNumber)
	{
		Q_ASSERT_X(false, "WorldRuntime::luaCallbackOutputAnchorBufferIndex",
		           "Callback output anchor position was not reconciled by a structural mutation");
		return 0;
	}
	return luaContextBufferPresentation().bufferIndexForPhysicalIndex(static_cast<int>(physicalIndex));
}

int WorldRuntime::openOutputPrefixColumnsBeforeIndex(const int insertionIndex) const
{
	int columns = 0;
	for (int index = qMin(insertionIndex, safeQSizeToInt(m_lines.size())) - 1; index >= 0; --index)
	{
		const LineEntry &entry = m_lines.at(index);
		if ((entry.flags & LineHidden) != 0)
			continue;
		if (entry.hardReturn)
			break;
		const int entryColumns = trailingLineColumnWidthForWrap(entry.text);
		if (entryColumns > std::numeric_limits<int>::max() - columns)
			return std::numeric_limits<int>::max();
		columns += entryColumns;
	}
	return columns;
}

QString WorldRuntime::openOutputTextBeforeIndex(const int insertionIndex) const
{
	QStringList parts;
	for (int index = qMin(insertionIndex, safeQSizeToInt(m_lines.size())) - 1; index >= 0; --index)
	{
		const LineEntry &entry = m_lines.at(index);
		if ((entry.flags & LineHidden) != 0)
			continue;
		if (entry.hardReturn)
			break;
		parts.prepend(entry.text);
	}
	return parts.join(QString());
}

bool WorldRuntime::writeLuaCallbackOutputSegmentsAtLineAnchor(
    const qint64 anchorLineNumber, const int anchorRelativeOffset, const bool replaceAnchor,
    const LuaCallbackOutputPosition &position, const QVector<LineEntry> &segments, const int flags,
    const quint64 outputStreamId, const QStringList &screenDrawLines,
    const std::shared_ptr<LuaCallbackOutputAnchorState> &anchorState, int *const resolvedAnchorBufferIndex)
{
	if (m_sessionStateOutputBufferSealed || anchorLineNumber <= 0 || anchorRelativeOffset < 0 ||
	    segments.isEmpty())
	{
		return false;
	}
	const int segmentCount = safeQSizeToInt(segments.size());
	const int anchorIndex  = position.anchorIndex;
	if (anchorIndex < 0 || anchorIndex >= m_lines.size() ||
	    m_lines.at(anchorIndex).lineNumber != anchorLineNumber)
	{
		const LuaCallbackOutputCursorKey key{outputStreamId, anchorLineNumber};
		auto                             cursorIt = m_luaCallbackAfterAnchorInsertionCursors.find(key);
		if (cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end())
		{
			if (cursorIt->trackedAnchorState)
				cursorIt->trackedAnchorState->clearPresentation();
			unindexLuaCallbackOutputCursor(key);
			m_luaCallbackAfterAnchorInsertionCursors.erase(cursorIt);
		}
		return false;
	}

	const bool effectiveReplaceAnchor = replaceAnchor && position.insertionIndex == position.anchorIndex;
	if (effectiveReplaceAnchor && (m_lines.at(anchorIndex).flags & LineHidden) == 0)
		return false;
	if (anchorState)
	{
		auto cursorIt = m_luaCallbackAfterAnchorInsertionCursors.find({outputStreamId, anchorLineNumber});
		if (cursorIt == m_luaCallbackAfterAnchorInsertionCursors.end())
			return false;
		if (cursorIt->trackedAnchorState && cursorIt->trackedAnchorState != anchorState)
		{
			Q_ASSERT_X(false, "WorldRuntime::writeLuaCallbackOutputSegmentsAtLineAnchor",
			           "Callback output cursor was rebound to a different anchor state");
			return false;
		}
		if (!cursorIt->trackedAnchorState)
		{
			anchorState->bindHeadRemovalCount(m_luaCallbackOutputHeadRemovalCount);
			cursorIt->trackedAnchorState = anchorState;
			refreshTrackedLuaCallbackOutputAnchor({outputStreamId, anchorLineNumber}, *cursorIt,
			                                      luaContextBufferPresentation());
		}
	}

	auto makeInsertedEntry = [&](const LineEntry &segment)
	{
		LineEntry entry;
		entry.text       = segment.text;
		entry.flags      = flags & ~LineHidden;
		entry.spans      = segment.spans;
		entry.hardReturn = segment.hardReturn;
		entry.time       = QDateTime::currentDateTimeUtc();
		entry.lineNumber = m_nextLineNumber++;
		if (m_lineTimer.isValid())
		{
			entry.ticks   = static_cast<double>(m_lineTimer.nsecsElapsed()) / 1000000000.0;
			entry.elapsed = entry.ticks;
		}
		else
		{
			const double fallback = (m_worldStartTime.isValid() && entry.time.isValid())
			                            ? static_cast<double>(m_worldStartTime.msecsTo(entry.time)) / 1000.0
			                            : 0.0;
			entry.ticks           = fallback;
			entry.elapsed         = fallback;
		}
		return entry;
	};
	auto makeInsertedEntries = [&](const int firstSegmentIndex)
	{
		QVector<LineEntry> entries;
		entries.reserve(segmentCount - firstSegmentIndex);
		for (int index = firstSegmentIndex; index < segmentCount; ++index)
			entries.push_back(makeInsertedEntry(segments.at(index)));
		return entries;
	};
	auto fireCompletedLines = [&](const int outputFlags)
	{
		if ((outputFlags & LineHorizontalRule) != 0)
			return;
		const int type = (outputFlags & LineNote) != 0 ? 1 : ((outputFlags & LineInput) != 0 ? 2 : 0);
		const int log  = (outputFlags & LineLog) != 0 ? 1 : 0;
		for (const QString &line : screenDrawLines)
			firePluginScreendraw(type, log, line);
	};

	if (effectiveReplaceAnchor)
	{
		const int  preMutationSize    = safeQSizeToInt(m_lines.size());
		const bool mutationIsAtTail   = anchorIndex == preMutationSize - 1;
		int        firstChangedIndex  = anchorIndex;
		bool       closedPreviousLine = false;
		int        previousFlags      = 0;
		QString    previousLineText;
		if ((flags & LineHorizontalRule) != 0 && anchorIndex > 0)
		{
			LineEntry &previous = m_lines[anchorIndex - 1];
			if (!previous.hardReturn && !previous.text.isEmpty())
			{
				previousLineText    = openOutputTextBeforeIndex(anchorIndex);
				previousFlags       = previous.flags;
				previous.hardReturn = true;
				firstChangedIndex   = anchorIndex - 1;
				closedPreviousLine  = true;
			}
		}
		const LineEntry &firstSegment = segments.first();
		LineEntry       &entry        = m_lines[anchorIndex];
		entry.text                    = firstSegment.text;
		entry.flags                   = flags & ~LineHidden;
		entry.spans                   = firstSegment.spans;
		entry.hardReturn              = firstSegment.hardReturn;
		insertOutputLineRange(anchorIndex + 1, makeInsertedEntries(1));
		auto cursorIt = m_luaCallbackAfterAnchorInsertionCursors.find({outputStreamId, anchorLineNumber});
		Q_ASSERT(cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end());
		cursorIt->anchorPosition   = m_luaCallbackOutputIndexOrigin + anchorIndex;
		const int cursorIndex      = anchorIndex + segmentCount - 1;
		cursorIt->cursorPosition   = m_luaCallbackOutputIndexOrigin + cursorIndex;
		cursorIt->cursorLineNumber = m_lines.at(cursorIndex).lineNumber;
		if (m_luaContextLineState == LuaContextLineState::AwaitingReplacement &&
		    m_luaContextLineNumber == anchorLineNumber)
		{
			m_luaContextLineState = LuaContextLineState::Buffered;
		}
		refreshTrackedLuaCallbackOutputAnchorsForLine(anchorLineNumber);
		const int removedHeadCount = enforceOutputLineLimit();
		invalidateLuaCallbackLineBufferSnapshot();
		if (!m_lines.isEmpty())
		{
			const int postMutationSize = safeQSizeToInt(m_lines.size());
			if (mutationIsAtTail)
			{
				const int changedFirst  = qBound(0, firstChangedIndex - removedHeadCount, postMutationSize);
				const int changedLast   = qBound(0, anchorIndex + 1 - removedHeadCount, postMutationSize);
				const int appendedFirst = qBound(0, preMutationSize - removedHeadCount, postMutationSize);
				const OutputBufferEdit structuralEdit{anchorIndex, 1, segmentCount};
				if (changedFirst < changedLast && appendedFirst < postMutationSize)
				{
					notifyOutputViewTailRangeChangedAndLinesAppended(changedFirst, changedLast, appendedFirst,
					                                                 postMutationSize, structuralEdit,
					                                                 removedHeadCount);
				}
				else if (changedFirst < changedLast)
				{
					notifyOutputViewRangeChanged(changedFirst, changedLast, structuralEdit, removedHeadCount);
				}
				else if (appendedFirst < postMutationSize)
				{
					notifyOutputViewLinesAppended(appendedFirst, postMutationSize, structuralEdit,
					                              removedHeadCount);
				}
			}
			else
			{
				const int notifyIndex = qBound(0, firstChangedIndex - removedHeadCount, postMutationSize - 1);
				const int changedEndExclusive =
				    qBound(notifyIndex, anchorIndex + segmentCount - removedHeadCount, postMutationSize);
				notifyOutputViewRangeChanged(notifyIndex, changedEndExclusive, {anchorIndex, 1, segmentCount},
				                             removedHeadCount);
			}
		}
		if (closedPreviousLine)
		{
			const int previousType =
			    (previousFlags & LineNote) != 0 ? 1 : ((previousFlags & LineInput) != 0 ? 2 : 0);
			firePluginScreendraw(previousType, (previousFlags & LineLog) != 0 ? 1 : 0, previousLineText);
		}
		fireCompletedLines(flags);
		if (resolvedAnchorBufferIndex)
		{
			*resolvedAnchorBufferIndex = luaCallbackOutputAnchorBufferIndex(outputStreamId, anchorLineNumber);
		}
		return true;
	}

	const int insertIndex     = position.insertionIndex;
	const int preMutationSize = safeQSizeToInt(m_lines.size());
	if (insertIndex < 0 || insertIndex > m_lines.size())
		return false;
	int     firstChangedIndex  = insertIndex;
	bool    closedPreviousLine = false;
	int     previousFlags      = 0;
	QString previousLineText;
	if ((flags & LineHorizontalRule) != 0 && insertIndex > 0)
	{
		LineEntry &previous = m_lines[insertIndex - 1];
		if (!previous.hardReturn && !previous.text.isEmpty())
		{
			previousLineText    = openOutputTextBeforeIndex(insertIndex);
			previousFlags       = previous.flags;
			previous.hardReturn = true;
			firstChangedIndex   = insertIndex - 1;
			closedPreviousLine  = true;
		}
	}
	insertOutputLineRange(insertIndex, makeInsertedEntries(0));
	const bool convertedReplacementToAppend = replaceAnchor && !effectiveReplaceAnchor;
	if (anchorRelativeOffset > 0 || convertedReplacementToAppend)
	{
		auto cursorIt = m_luaCallbackAfterAnchorInsertionCursors.find({outputStreamId, anchorLineNumber});
		Q_ASSERT(cursorIt != m_luaCallbackAfterAnchorInsertionCursors.end());
		const int cursorIndex      = insertIndex + segmentCount - 1;
		cursorIt->cursorPosition   = m_luaCallbackOutputIndexOrigin + cursorIndex;
		cursorIt->cursorLineNumber = m_lines.at(cursorIndex).lineNumber;
	}
	const int removedHeadCount = enforceOutputLineLimit();
	invalidateLuaCallbackLineBufferSnapshot();
	if (!m_lines.isEmpty())
	{
		const int postMutationSize = safeQSizeToInt(m_lines.size());
		if (insertIndex == preMutationSize)
		{
			const int appendedFirst = qBound(0, insertIndex - removedHeadCount, postMutationSize);
			const OutputBufferEdit structuralEdit{insertIndex, 0, segmentCount};
			if (!closedPreviousLine)
			{
				if (appendedFirst < postMutationSize)
				{
					notifyOutputViewLinesAppended(appendedFirst, postMutationSize, structuralEdit,
					                              removedHeadCount);
				}
			}
			else
			{
				const int changedFirst = qBound(0, firstChangedIndex - removedHeadCount, postMutationSize);
				const int changedLast  = qBound(0, insertIndex - removedHeadCount, postMutationSize);
				if (changedFirst < changedLast && appendedFirst < postMutationSize)
				{
					notifyOutputViewTailRangeChangedAndLinesAppended(changedFirst, changedLast, appendedFirst,
					                                                 postMutationSize, structuralEdit,
					                                                 removedHeadCount);
				}
				else if (changedFirst < changedLast)
				{
					notifyOutputViewRangeChanged(changedFirst, changedLast, structuralEdit, removedHeadCount);
				}
				else if (appendedFirst < postMutationSize)
				{
					notifyOutputViewLinesAppended(appendedFirst, postMutationSize, structuralEdit,
					                              removedHeadCount);
				}
			}
		}
		else
		{
			const int notifyIndex = qBound(0, firstChangedIndex - removedHeadCount, postMutationSize - 1);
			const int changedEndExclusive =
			    qBound(notifyIndex, insertIndex + segmentCount - removedHeadCount, postMutationSize);
			notifyOutputViewRangeChanged(notifyIndex, changedEndExclusive, {insertIndex, 0, segmentCount},
			                             removedHeadCount);
		}
	}
	if (closedPreviousLine)
	{
		const int previousType =
		    (previousFlags & LineNote) != 0 ? 1 : ((previousFlags & LineInput) != 0 ? 2 : 0);
		firePluginScreendraw(previousType, (previousFlags & LineLog) != 0 ? 1 : 0, previousLineText);
	}
	fireCompletedLines(flags);
	if (resolvedAnchorBufferIndex)
		*resolvedAnchorBufferIndex = luaCallbackOutputAnchorBufferIndex(outputStreamId, anchorLineNumber);
	return true;
}

void WorldRuntime::endIncomingLineLuaContext()
{
	if (m_luaContextLineState == LuaContextLineState::AwaitingReplacement)
	{
		if (m_sessionStateOutputBufferSealed)
		{
			m_deferredHiddenLuaContextLineBufferIndex = m_luaContextLineBufferIndex;
			m_deferredHiddenLuaContextLineNumber      = m_luaContextLineNumber;
			resetIncomingLineLuaContext();
			invalidateLuaCallbackLineBufferSnapshot();
			return;
		}
		const int hiddenIndex = m_luaContextLineBufferIndex - 1;
		if (hiddenIndex >= 0 && hiddenIndex < m_lines.size() &&
		    m_lines.at(hiddenIndex).lineNumber == m_luaContextLineNumber &&
		    (m_lines.at(hiddenIndex).flags & LineHidden) != 0)
		{
			const int removedCount      = removeOutputLineRange(hiddenIndex, 1);
			const int firstChangedIndex = qMax(0, qMin(hiddenIndex, safeQSizeToInt(m_lines.size()) - 1));
			notifyOutputViewRangeChanged(firstChangedIndex, hiddenIndex, {hiddenIndex, removedCount, 0},
			                             hiddenIndex == 0 ? removedCount : 0);
		}
	}
	resetIncomingLineLuaContext();
	invalidateLuaCallbackLineBufferSnapshot();
}

void WorldRuntime::resetIncomingLineLuaContext()
{
	const qint64 previousLineNumber = m_luaContextLineNumber;
	m_luaContextLineState           = LuaContextLineState::Inactive;
	m_luaContextLineBufferIndex     = 0;
	m_luaContextLineNumber          = 0;
	m_luaPendingContextLineEntry    = {};
	refreshTrackedLuaCallbackOutputAnchorsForLine(previousLineNumber);
}

WorldRuntime::IncomingLineLuaContextState WorldRuntime::captureIncomingLineLuaContextState() const
{
	IncomingLineLuaContextState state;
	state.state        = m_luaContextLineState;
	state.bufferIndex  = m_luaContextLineBufferIndex;
	state.lineNumber   = m_luaContextLineNumber;
	state.pendingEntry = m_luaPendingContextLineEntry;
	return state;
}

void WorldRuntime::restoreIncomingLineLuaContextState(const IncomingLineLuaContextState &state)
{
	m_luaContextLineState        = state.state;
	m_luaContextLineBufferIndex  = state.bufferIndex;
	m_luaContextLineNumber       = state.lineNumber;
	m_luaPendingContextLineEntry = state.pendingEntry;
	invalidateLuaCallbackLineBufferSnapshot();
}

void WorldRuntime::removeDeferredHiddenIncomingLine()
{
	if (m_sessionStateOutputBufferSealed || m_deferredHiddenLuaContextLineNumber <= 0)
	{
		return;
	}

	int hiddenIndex = deferredHiddenIncomingLineIndex();
	if (hiddenIndex < 0)
	{
		for (int index = safeQSizeToInt(m_lines.size()) - 1; index >= 0; --index)
		{
			if (m_lines.at(index).lineNumber == m_deferredHiddenLuaContextLineNumber)
			{
				hiddenIndex = index;
				break;
			}
		}
	}
	if (hiddenIndex >= 0 && (m_lines.at(hiddenIndex).flags & LineHidden) != 0)
	{
		const int removedCount      = removeOutputLineRange(hiddenIndex, 1);
		const int firstChangedIndex = qMax(0, qMin(hiddenIndex, safeQSizeToInt(m_lines.size()) - 1));
		notifyOutputViewRangeChanged(firstChangedIndex, hiddenIndex, {hiddenIndex, removedCount, 0},
		                             hiddenIndex == 0 ? removedCount : 0);
	}
	m_deferredHiddenLuaContextLineBufferIndex = 0;
	m_deferredHiddenLuaContextLineNumber      = 0;
	invalidateLuaCallbackLineBufferSnapshot();
}

int WorldRuntime::deferredHiddenIncomingLineIndex() const
{
	const int hiddenIndex = m_deferredHiddenLuaContextLineBufferIndex - 1;
	if (hiddenIndex < 0 || hiddenIndex >= m_lines.size() ||
	    m_lines.at(hiddenIndex).lineNumber != m_deferredHiddenLuaContextLineNumber ||
	    (m_lines.at(hiddenIndex).flags & LineHidden) == 0)
	{
		return -1;
	}
	return hiddenIndex;
}

void WorldRuntime::markIncomingLineLuaContextBuffered()
{
	if (m_luaContextLineState == LuaContextLineState::Inactive ||
	    m_luaContextLineState == LuaContextLineState::Removed ||
	    m_luaContextLineState == LuaContextLineState::Committed)
		return;
	if (m_luaContextLineState == LuaContextLineState::Buffered ||
	    m_luaContextLineState == LuaContextLineState::AwaitingReplacement)
	{
		if (luaContextLinePresentInBuffer())
			m_luaPendingContextLineEntry = {};
		else
		{
			m_luaContextLineState       = LuaContextLineState::Removed;
			m_luaContextLineBufferIndex = 0;
		}
		invalidateLuaCallbackLineBufferSnapshot();
		return;
	}
	for (int index = safeQSizeToInt(m_lines.size()) - 1; index >= 0; --index)
	{
		if (m_lines.at(index).lineNumber != m_luaContextLineNumber)
			continue;
		m_luaContextLineState        = LuaContextLineState::Buffered;
		m_luaContextLineBufferIndex  = index + 1;
		m_luaPendingContextLineEntry = {};
		break;
	}
	invalidateLuaCallbackLineBufferSnapshot();
}

void WorldRuntime::markIncomingLineLuaContextCommitted()
{
	if (m_luaContextLineState == LuaContextLineState::Inactive ||
	    m_luaContextLineState == LuaContextLineState::Removed)
		return;
	m_luaContextLineState = LuaContextLineState::Committed;
	invalidateLuaCallbackLineBufferSnapshot();
}

int WorldRuntime::incomingLineLuaContextBufferIndex() const
{
	if (QThread::currentThread() != thread())
	{
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), 0,
		                          [this] { return incomingLineLuaContextBufferIndex(); });
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::incomingLineLuaContextBufferIndex");
	if (m_luaContextLineState == LuaContextLineState::Pending)
		return safeQSizeToInt(m_lines.size() + 1);
	if (m_luaContextLineState != LuaContextLineState::Buffered &&
	    m_luaContextLineState != LuaContextLineState::AwaitingReplacement &&
	    m_luaContextLineState != LuaContextLineState::Committed)
	{
		return 0;
	}
	const int lineIndex = m_luaContextLineBufferIndex - 1;
	if (lineIndex < 0 || lineIndex >= m_lines.size() ||
	    m_lines.at(lineIndex).lineNumber != m_luaContextLineNumber)
	{
		return 0;
	}
	return m_luaContextLineBufferIndex;
}

bool WorldRuntime::luaContextLinePresentInBuffer() const
{
	if ((m_luaContextLineState != LuaContextLineState::Buffered &&
	     m_luaContextLineState != LuaContextLineState::AwaitingReplacement) ||
	    m_luaContextLineBufferIndex <= 0 || m_luaContextLineBufferIndex > m_lines.size())
	{
		return false;
	}
	return m_lines.at(m_luaContextLineBufferIndex - 1).lineNumber == m_luaContextLineNumber;
}

bool WorldRuntime::luaContextLineEntry(int lineNumber, LineEntry &entry) const
{
	if (lineNumber <= 0)
		return false;

	const LuaContextBufferPresentation presentation = luaContextBufferPresentation();
	if (const LineEntry *const storedEntry = luaContextStoredLineEntryAtBufferIndex(lineNumber, presentation))
	{
		entry = *storedEntry;
		return true;
	}

	if (presentation.hasPendingLine && lineNumber == presentation.lineCount())
	{
		entry            = m_luaPendingContextLineEntry;
		entry.lineNumber = m_luaContextLineNumber;
		return true;
	}
	return false;
}

WorldRuntime::LuaContextBufferPresentation WorldRuntime::luaContextBufferPresentation() const
{
	return {
	    safeQSizeToInt(m_lines.size()),
	    deferredHiddenIncomingLineIndex(),
	    m_luaContextLineState == LuaContextLineState::Pending,
	};
}

const WorldRuntime::LineEntry *
WorldRuntime::luaContextStoredLineEntryAtBufferIndex(const int                           bufferIndex,
                                                     const LuaContextBufferPresentation &presentation) const
{
	const int physicalIndex = presentation.physicalIndexForBufferIndex(bufferIndex);
	if (physicalIndex < 0 || physicalIndex >= m_lines.size())
		return nullptr;
	return &m_lines.at(physicalIndex);
}

bool WorldRuntime::resolveLuaCallbackMatchedLineEntry(const int    preferredBufferIndex,
                                                      const qint64 absoluteLineNumber,
                                                      int &resolvedBufferIndex, LineEntry &entry) const
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::resolveLuaCallbackMatchedLineEntry");
	resolvedBufferIndex = 0;
	if (absoluteLineNumber <= 0)
		return false;

	const LuaContextBufferPresentation presentation = luaContextBufferPresentation();
	auto acceptStoredEntry                          = [&](const int bufferIndex, const LineEntry &candidate)
	{
		entry               = candidate;
		resolvedBufferIndex = bufferIndex;
		return true;
	};
	auto acceptPendingEntry = [&]
	{
		entry               = m_luaPendingContextLineEntry;
		entry.lineNumber    = m_luaContextLineNumber;
		resolvedBufferIndex = presentation.lineCount();
		return true;
	};
	if (m_luaContextLineNumber == absoluteLineNumber)
	{
		if (presentation.hasPendingLine)
			return acceptPendingEntry();
		const int physicalIndex      = m_luaContextLineBufferIndex - 1;
		const int currentBufferIndex = presentation.bufferIndexForPhysicalIndex(physicalIndex);
		if (currentBufferIndex > 0 && physicalIndex >= 0 && physicalIndex < m_lines.size() &&
		    m_lines.at(physicalIndex).lineNumber == absoluteLineNumber)
		{
			return acceptStoredEntry(currentBufferIndex, m_lines.at(physicalIndex));
		}
	}

	if (const LineEntry *const preferredEntry =
	        luaContextStoredLineEntryAtBufferIndex(preferredBufferIndex, presentation);
	    preferredEntry && preferredEntry->lineNumber == absoluteLineNumber)
	{
		return acceptStoredEntry(preferredBufferIndex, *preferredEntry);
	}
	if (presentation.hasPendingLine && preferredBufferIndex == presentation.lineCount() &&
	    m_luaContextLineNumber == absoluteLineNumber)
	{
		return acceptPendingEntry();
	}

	return false;
}

bool WorldRuntime::luaContextLineEntryByAbsoluteNumber(const qint64 absoluteLineNumber,
                                                       LineEntry   &entry) const
{
	if (absoluteLineNumber <= 0)
		return false;

	if (QThread::currentThread() != thread())
	{
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), false, [this, absoluteLineNumber, &entry]
		                          { return luaContextLineEntryByAbsoluteNumber(absoluteLineNumber, entry); });
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::luaContextLineEntryByAbsoluteNumber");
	if (m_deferredHiddenLuaContextLineNumber > 0 &&
	    absoluteLineNumber == m_deferredHiddenLuaContextLineNumber)
	{
		return false;
	}
	if (m_luaContextLineState == LuaContextLineState::Pending)
	{
		if (m_luaContextLineNumber == absoluteLineNumber)
		{
			entry = m_luaPendingContextLineEntry;
			if (entry.lineNumber <= 0)
				entry.lineNumber = m_luaContextLineNumber;
			return true;
		}
	}
	else if ((m_luaContextLineState == LuaContextLineState::Buffered ||
	          m_luaContextLineState == LuaContextLineState::AwaitingReplacement) &&
	         m_luaContextLineNumber == absoluteLineNumber && luaContextLinePresentInBuffer())
	{
		entry = m_lines.at(m_luaContextLineBufferIndex - 1);
		return true;
	}

	for (const LineEntry &line : m_lines)
	{
		if (line.lineNumber != absoluteLineNumber)
			continue;
		entry = line;
		return true;
	}
	return false;
}

int WorldRuntime::luaContextLinePageByBufferIndex(const int firstBufferIndex, const int lastBufferIndex,
                                                  quint64               &lineBufferGeneration,
                                                  QHash<int, LineEntry> &entries,
                                                  QStringList           &recentLinesSnapshot,
                                                  const bool             includeRecentLines) const
{
	if (QThread::currentThread() != thread())
	{
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), 0,
		                          [this, firstBufferIndex, lastBufferIndex, &lineBufferGeneration, &entries,
		                           &recentLinesSnapshot, includeRecentLines]
		                          {
			                          return luaContextLinePageByBufferIndex(
			                              firstBufferIndex, lastBufferIndex, lineBufferGeneration, entries,
			                              recentLinesSnapshot, includeRecentLines);
		                          });
	}
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::luaContextLinePageByBufferIndex");
	entries.clear();
	recentLinesSnapshot.clear();
	lineBufferGeneration = m_luaCallbackLineBufferSnapshotGeneration;
	if (includeRecentLines)
		recentLinesSnapshot = recentLines();
	const int lineBufferCount = luaContextLinesInBufferCount();
	if (firstBufferIndex == 0 && lastBufferIndex == 0)
	{
		if (lineBufferCount > 0)
		{
			LineEntry entry;
			if (luaContextLineEntry(lineBufferCount, entry))
				entries.insert(lineBufferCount, std::move(entry));
		}
		return lineBufferCount;
	}
	if (firstBufferIndex <= 0 || lastBufferIndex < firstBufferIndex)
		return lineBufferCount;
	const int boundedLastBufferIndex = qMin(lastBufferIndex, lineBufferCount);
	for (int lineNumber = firstBufferIndex; lineNumber <= boundedLastBufferIndex; ++lineNumber)
	{
		LineEntry entry;
		if (luaContextLineEntry(lineNumber, entry))
			entries.insert(lineNumber, std::move(entry));
	}
	return lineBufferCount;
}

int WorldRuntime::luaContextLinesInBufferCount() const
{
	if (QThread::currentThread() != thread())
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), 0,
		                          [this] { return luaContextLinesInBufferCount(); });

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::luaContextLinesInBufferCount");
	return luaContextBufferPresentation().lineCount();
}

QSharedPointer<const LuaCallbackSnapshot>
WorldRuntime::luaCallbackSnapshotForBridgedCall(const QString &geometryConstrainedMiniWindowName) const
{
	auto snapshot =
	    captureLuaCallbackSnapshotForDispatchMutable({}, LuaCallbackLineSnapshotPolicy::CountAndLast);
	if (!snapshot || geometryConstrainedMiniWindowName.isEmpty())
		return snapshot;
	const MiniWindowGeometryConstraintSnapshot geometry = miniWindowGeometryConstraintSnapshot();
	snapshot->geometryConstrainedMiniWindowName         = geometryConstrainedMiniWindowName;
	snapshot->geometryConstraintDisplayClientHeight     = geometry.displayClientHeight;
	snapshot->geometryConstraintDisplayClientWidth      = geometry.displayClientWidth;
	snapshot->absoluteMiniWindowScaleXOver              = geometry.scaleXOver;
	snapshot->absoluteMiniWindowScaleYOver              = geometry.scaleYOver;
	snapshot->absoluteMiniWindowScaleXUnder             = geometry.scaleXUnder;
	snapshot->absoluteMiniWindowScaleYUnder             = geometry.scaleYUnder;
	return snapshot;
}

int WorldRuntime::windowCreate(const QString &name, int left, int top, int width, int height, int position,
                               int flags, const QColor &background, const QString &pluginId)
{
	if (name.isEmpty())
		return eNoNameSpecified;
	if (width < 0 || height < 0)
		return eBadParameter;
	auto it = m_miniWindows.find(name);
	if (it == m_miniWindows.end())
	{
		MiniWindow window;
		window.runtimeId = nextMiniWindowRuntimeId();
		window.name      = name;
		it               = m_miniWindows.insert(name, window);
	}
	else if (it->runtimeId == 0)
	{
		it->runtimeId = nextMiniWindowRuntimeId();
	}

	MiniWindow &window            = it.value();
	const auto  previousMouseOver = captureMiniWindowHotspotInteraction(window, window.mouseOverHotspot);
	const auto previousMouseDown = window.mouseDownHotspot == window.mouseOverHotspot
	                                   ? std::nullopt
	                                   : captureMiniWindowHotspotInteraction(window, window.mouseDownHotspot);
	MiniWindowUtils::create(window, name, left, top, width, height, position, flags, background, pluginId,
	                        miniWindowDevicePixelRatioForView(m_view));
	if (previousMouseOver)
		reconcileMiniWindowHotspotInteractionAfterMutation(
		    name, previousMouseOver->hotspotId, previousMouseOver->instanceId, previousMouseOver->tooltip);
	if (previousMouseDown)
		reconcileMiniWindowHotspotInteractionAfterMutation(
		    name, previousMouseDown->hotspotId, previousMouseDown->instanceId, previousMouseDown->tooltip);

	emitMiniWindowsChangedCoalesced(name);
	return eOK;
}

int WorldRuntime::windowShow(const QString &name, bool show)
{
	const auto it = m_miniWindows.find(name);
	if (it == m_miniWindows.end())
		return eNoSuchWindow;
	if (it->show == show)
		return eOK;
	it.value().show = show;
	emitMiniWindowsChangedCoalesced(name, LuaCallbackMiniWindowSnapshotChange::WindowInfo);
	return eOK;
}

int WorldRuntime::windowDelete(const QString &name)
{
	const auto it = m_miniWindows.find(name);
	if (it == m_miniWindows.end())
		return eNoSuchWindow;
	if (it.value().executingScript)
		return eItemInUse;
	const auto previousMouseOver = captureMiniWindowHotspotInteraction(*it, it->mouseOverHotspot);
	const auto previousMouseDown = it->mouseDownHotspot == it->mouseOverHotspot
	                                   ? std::nullopt
	                                   : captureMiniWindowHotspotInteraction(*it, it->mouseDownHotspot);
	m_miniWindows.erase(it);
	if (previousMouseOver)
		reconcileMiniWindowHotspotInteractionAfterMutation(
		    name, previousMouseOver->hotspotId, previousMouseOver->instanceId, previousMouseOver->tooltip);
	if (previousMouseDown)
		reconcileMiniWindowHotspotInteractionAfterMutation(
		    name, previousMouseDown->hotspotId, previousMouseDown->instanceId, previousMouseDown->tooltip);
	emitMiniWindowsChangedCoalesced(name);
	return eOK;
}

void WorldRuntime::beginMiniWindowMutationBatch()
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::beginMiniWindowMutationBatch");
	++m_miniWindowMutationBatchDepth;
}

void WorldRuntime::endMiniWindowMutationBatch()
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::endMiniWindowMutationBatch");
	if (m_miniWindowMutationBatchDepth <= 0)
	{
		m_miniWindowMutationBatchDepth = 0;
		m_miniWindowsChangedPending    = false;
		return;
	}
	--m_miniWindowMutationBatchDepth;
	if (m_miniWindowMutationBatchDepth == 0 && m_miniWindowsChangedPending)
	{
		m_miniWindowsChangedPending = false;
		emit miniWindowsChanged();
	}
	if (m_miniWindowMutationBatchDepth == 0)
		scheduleMiniWindowAddedHotspotHoverCheck();
}

void WorldRuntime::emitMiniWindowsChangedCoalesced(const QString &windowName)

{
	emitMiniWindowsChangedCoalesced(windowName, luaCallbackAllMiniWindowSnapshotChanges());
}

void WorldRuntime::emitMiniWindowsChangedCoalesced(const QString                             &windowName,
                                                   const LuaCallbackMiniWindowSnapshotChanges changes)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::emitMiniWindowsChangedCoalesced");
	if (m_suppressMiniWindowsChangedPublication)
		return;
	patchLuaCallbackMiniWindowSnapshot(windowName, changes);
	if (m_miniWindowMutationBatchDepth > 0)
	{
		m_miniWindowsChangedPending = true;
		return;
	}
	emit miniWindowsChanged();
}

void WorldRuntime::emitMiniWindowsChangedCoalesced(
    const QHash<QString, LuaCallbackMiniWindowSnapshotChanges> &windows)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::emitMiniWindowsChangedCoalesced");
	if (m_suppressMiniWindowsChangedPublication || windows.isEmpty())
		return;
	for (auto window = windows.constBegin(); window != windows.constEnd(); ++window)
		patchLuaCallbackMiniWindowSnapshot(window.key(), window.value());
	if (m_miniWindowMutationBatchDepth > 0)
	{
		m_miniWindowsChangedPending = true;
		return;
	}
	emit miniWindowsChanged();
}

void WorldRuntime::patchLuaCallbackMiniWindowSnapshot(const QString                             &windowName,
                                                      const LuaCallbackMiniWindowSnapshotChanges changes)
{
	if (++m_luaCallbackMiniWindowStableRevision == 0)
		++m_luaCallbackMiniWindowStableRevision;
	if (auto window = m_miniWindows.find(windowName); window != m_miniWindows.end())
	{
		if (window->runtimeId == 0)
			window->runtimeId = nextMiniWindowRuntimeId();
		if (++window->mutationRevision == 0)
			++window->mutationRevision;
	}
	publishMiniWindowPresentation(windowName);
	LuaCallbackStableSnapshotPatchScope scope = LuaCallbackStableSnapshotPatchScope::item({}, windowName);
	scope.miniWindowChanges                   = changes;
	patchLuaCallbackStableSnapshot(LuaCallbackStableSnapshotDomain::MiniWindows, scope);
}

void WorldRuntime::publishMiniWindowPresentation(const QString &windowName)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::publishMiniWindowPresentation");
	using Presentation = LuaCallbackMiniWindowsSnapshotState::PresentationSnapshot;
	const auto window  = m_miniWindows.constFind(windowName);
	if (window == m_miniWindows.constEnd() || window->runtimeId == 0)
	{
		const quint64 runtimeId = m_luaCallbackMiniWindowPresentationRuntimeIdByName.take(windowName);
		if (runtimeId != 0)
		{
			m_luaCallbackMiniWindowPresentationByRuntimeId =
			    m_luaCallbackMiniWindowPresentationByRuntimeId.withUpdates({
			        {static_cast<quint32>(runtimeId), {}}
            });
			if (!m_causalPluginCallbackSnapshotCaptureStack.isEmpty())
				m_causalPluginCallbackSnapshotCaptureStack.last()->miniWindowPresentationMutations.insert(
				    windowName, {runtimeId, std::nullopt});
		}
		return;
	}
	Presentation row;
	row.runtimeId                   = window->runtimeId;
	row.rect                        = window->rect;
	row.temporarilyHide             = window->temporarilyHide;
	row.lastMousePosition           = window->lastMousePosition;
	row.lastMouseUpdate             = window->lastMouseUpdate;
	row.clientMousePosition         = window->clientMousePosition;
	row.mouseOverHotspot            = window->mouseOverHotspot;
	row.mouseDownHotspot            = window->mouseDownHotspot;
	const quint64 previousRuntimeId = m_luaCallbackMiniWindowPresentationRuntimeIdByName.value(windowName);
	const auto    slot              = static_cast<quint32>(window->runtimeId);
	const auto    old               = m_luaCallbackMiniWindowPresentationByRuntimeId.value(slot);
	if (old && *old == row)
		return;
	QVector<LuaCallbackPersistentSlotMap<Presentation>::Update> updates;
	if (previousRuntimeId != 0 && previousRuntimeId != window->runtimeId)
		updates.push_back({static_cast<quint32>(previousRuntimeId), {}});
	updates.push_back({slot, QSharedPointer<const Presentation>::create(row)});
	m_luaCallbackMiniWindowPresentationByRuntimeId =
	    m_luaCallbackMiniWindowPresentationByRuntimeId.withUpdates(updates);
	m_luaCallbackMiniWindowPresentationRuntimeIdByName.insert(windowName, window->runtimeId);
	if (!m_causalPluginCallbackSnapshotCaptureStack.isEmpty())
		m_causalPluginCallbackSnapshotCaptureStack.last()->miniWindowPresentationMutations.insert(
		    windowName, {window->runtimeId, std::move(row)});
}

void WorldRuntime::commitLuaCallbackMiniWindowStates(
    QHash<QString, MiniWindow> windows, const QSet<QString> &removedWindowNames,
    const QSet<QString> &replacedWindowNames, MiniWindowHotspotInstanceMap addedHotspots,
    const QHash<QString, LuaCallbackMiniWindowSnapshotChanges> &changesByWindow,
    const QHash<QString, QSharedPointer<const MiniWindow>>     &baseWindowsByName,
    const QSet<QString> &presentationChangedWindowNames, const MiniWindowHotspotMutationMap &hotspotMutations,
    const QSet<QString>                                                &forceDeltaMergeWindowNames,
    const QHash<QString, QSet<QString>>                                &mutatedFontIdsByWindow,
    const QHash<QString, QSet<QString>>                                &mutatedImageIdsByWindow,
    const QHash<QString, QVector<LuaCallbackMiniWindowResizeMutation>> &resizeMutationsByWindow,
    const QHash<QString, LuaCallbackMiniWindowCreateMutation>          &createMutationsByWindow,
    MiniWindowCommitOutcomeMap                                         *outcomes)
{
	qmudAssertObjectThreadAffinity(this, "WorldRuntime::commitLuaCallbackMiniWindowStates");
	const std::optional<double> viewDevicePixelRatio =
	    m_view ? std::optional(miniWindowDevicePixelRatioForView(m_view)) : std::nullopt;
	const auto applyValueDelta = []<typename T>(T &current, const T &before, const T &after)
	{
		if (after != before)
			current = after;
	};
	const auto applyMapDelta =
	    []<typename Value>(QMap<QString, Value> &current, const QMap<QString, Value> &before,
	                       const QMap<QString, Value> &after, const QSet<QString> &changedIds)
	{
		for (const QString &id : changedIds)
		{
			const auto beforeIt = before.constFind(id);
			const auto afterIt  = after.constFind(id);
			if (beforeIt != before.constEnd() && afterIt != after.constEnd() &&
			    beforeIt.value() == afterIt.value())
				continue;
			if (afterIt == after.constEnd())
				current.remove(id);
			else
				current.insert(id, afterIt.value());
		}
	};
	const auto applyTrackedMapValues = []<typename Value>(QMap<QString, Value>       &current,
	                                                      const QMap<QString, Value> &after,
	                                                      const QSet<QString>        &changedIds)
	{
		for (const QString &id : changedIds)
		{
			const auto afterIt = after.constFind(id);
			if (afterIt == after.constEnd())
				current.remove(id);
			else
				current.insert(id, afterIt.value());
		}
	};
	const auto mergeStaleShadow =
	    [&](MiniWindow &current, const MiniWindow &base, const MiniWindow &shadow,
	        const bool presentationChanged, const QHash<QString, MiniWindowHotspotMutation> &hotspotDelta,
	        const QSet<QString> &mutatedFontIds, const QSet<QString> &mutatedImageIds,
	        const QVector<LuaCallbackMiniWindowResizeMutation> &resizeMutations)
	{
		if (!presentationChanged)
		{
			for (const LuaCallbackMiniWindowResizeMutation &resize : resizeMutations)
				MiniWindowUtils::resize(current, resize.width, resize.height, resize.colour);
		}
		applyValueDelta(current.width, base.width, shadow.width);
		applyValueDelta(current.height, base.height, shadow.height);
		applyValueDelta(current.position, base.position, shadow.position);
		applyValueDelta(current.flags, base.flags, shadow.flags);
		applyValueDelta(current.background, base.background, shadow.background);
		applyValueDelta(current.show, base.show, shadow.show);
		applyValueDelta(current.location, base.location, shadow.location);
		applyValueDelta(current.zOrder, base.zOrder, shadow.zOrder);
		applyValueDelta(current.creatingPlugin, base.creatingPlugin, shadow.creatingPlugin);
		applyValueDelta(current.installedAt, base.installedAt, shadow.installedAt);
		applyMapDelta(current.fonts, base.fonts, shadow.fonts, mutatedFontIds);
		applyMapDelta(current.images, base.images, shadow.images, mutatedImageIds);
		QHash<QString, MiniWindowHotspotMutation> appliedHotspotDelta =
		    applyMiniWindowHotspotMutationJournal(current, hotspotDelta, shadow.callbackPlugin,
		                                          base.outputHotspotSerial, shadow.outputHotspotSerial);

		if (presentationChanged)
		{
			current.setBackingSurface(shadow.backingSurface());
			current.transparentSurfaceCache     = shadow.transparentSurfaceCache;
			current.transparentSurfaceSourceKey = shadow.transparentSurfaceSourceKey;
			current.transparentSurfaceKeyRgb    = shadow.transparentSurfaceKeyRgb;
		}
		return appliedHotspotDelta;
	};
	const auto applyCreateTransition =
	    [&](MiniWindow &current, const MiniWindow &base, const MiniWindow &shadow,
	        const LuaCallbackMiniWindowCreateMutation &create, const bool sharesCallbackBaseIdentity,
	        const QHash<QString, MiniWindowHotspotMutation> &hotspotDelta,
	        const QSet<QString> &mutatedFontIds, const QSet<QString> &mutatedImageIds,
	        const QVector<LuaCallbackMiniWindowResizeMutation> &resizeMutations)
	{
		if (create.clearHotspotsSinceBase)
			MiniWindowUtils::deleteAllHotspots(current);
		MiniWindowUtils::create(current, shadow.name, create.left, create.top, create.width, create.height,
		                        create.position, create.flags, create.background, create.pluginId,
		                        current.devicePixelRatio);
		current.installedAt = create.installedAt;
		for (const LuaCallbackMiniWindowResizeMutation &resize : resizeMutations)
			MiniWindowUtils::resize(current, resize.width, resize.height, resize.colour);
		current.location       = shadow.location;
		current.width          = shadow.width;
		current.height         = shadow.height;
		current.position       = shadow.position;
		current.flags          = shadow.flags;
		current.background     = shadow.background;
		current.show           = shadow.show;
		current.creatingPlugin = shadow.creatingPlugin;
		current.installedAt    = shadow.installedAt;
		if (create.zOrder)
			current.zOrder = *create.zOrder;
		if (sharesCallbackBaseIdentity)
		{
			applyMapDelta(current.fonts, base.fonts, shadow.fonts, mutatedFontIds);
			applyMapDelta(current.images, base.images, shadow.images, mutatedImageIds);
		}
		else
		{
			applyTrackedMapValues(current.fonts, shadow.fonts, mutatedFontIds);
			applyTrackedMapValues(current.images, shadow.images, mutatedImageIds);
		}
		const quint64 outputSerialBefore = create.clearHotspotsSinceBase ? 0 : base.outputHotspotSerial;
		QHash<QString, MiniWindowHotspotMutation> appliedHotspotDelta = applyMiniWindowHotspotMutationJournal(
		    current, hotspotDelta, shadow.callbackPlugin, outputSerialBefore, shadow.outputHotspotSerial);
		current.setBackingSurface(shadow.backingSurface());
		current.transparentSurfaceCache     = shadow.transparentSurfaceCache;
		current.transparentSurfaceSourceKey = shadow.transparentSurfaceSourceKey;
		current.transparentSurfaceKeyRgb    = shadow.transparentSurfaceKeyRgb;
		return appliedHotspotDelta;
	};
	const auto preserveRuntimeOnlyState =
	    [&](MiniWindow &committed, const MiniWindow &current, const bool preserveLayoutState)
	{
		const QString currentMouseOver      = current.mouseOverHotspot;
		const QString currentMouseDown      = current.mouseDownHotspot;
		const int     currentMouseDownFlags = current.flagsOnMouseDown;
		MiniWindowUtils::setDevicePixelRatio(committed,
		                                     viewDevicePixelRatio.value_or(current.devicePixelRatio));
		committed.runtimeId            = current.runtimeId;
		committed.mutationRevision     = current.mutationRevision;
		committed.executingScriptDepth = current.executingScriptDepth;
		committed.executingScript      = current.executingScript;
		committed.lastMousePosition    = current.lastMousePosition;
		committed.lastMouseUpdate      = current.lastMouseUpdate;
		committed.clientMousePosition  = current.clientMousePosition;
		if (preserveLayoutState)
		{
			committed.rect            = current.rect;
			committed.temporarilyHide = current.temporarilyHide;
		}
		const auto retainsHotspotIdentity = [&current, &committed](const QString &hotspotId)
		{
			if (hotspotId.isEmpty())
				return false;
			const auto currentHotspot   = current.hotspots.constFind(hotspotId);
			const auto committedHotspot = committed.hotspots.constFind(hotspotId);
			return currentHotspot != current.hotspots.constEnd() &&
			       committedHotspot != committed.hotspots.constEnd() && currentHotspot->instanceId != 0 &&
			       currentHotspot->instanceId == committedHotspot->instanceId;
		};
		committed.mouseOverHotspot = retainsHotspotIdentity(currentMouseOver) ? currentMouseOver : QString();
		if (retainsHotspotIdentity(currentMouseDown))
		{
			committed.mouseDownHotspot = currentMouseDown;
			committed.flagsOnMouseDown = currentMouseDownFlags;
		}
		else
		{
			committed.mouseDownHotspot.clear();
			committed.flagsOnMouseDown = 0;
		}
		return committed.mouseOverHotspot != currentMouseOver ||
		       committed.mouseDownHotspot != currentMouseDown;
	};
	const auto buildCausalDelta =
	    [&](const MiniWindow &base, const MiniWindow &shadow,
	        const QHash<QString, MiniWindowHotspotMutation> &appliedHotspots,
	        const QSet<QString> &mutatedFontIds, const QSet<QString> &mutatedImageIds,
	        const QVector<LuaCallbackMiniWindowResizeMutation> &resizeMutations,
	        const bool forceMapValues = false, const LuaCallbackMiniWindowCreateMutation *create = nullptr)
	{
		LuaCallbackMiniWindowCausalDelta delta;
		delta.expectedRuntimeId = base.runtimeId;
		const auto recordValue =
		    [&delta]<typename T>(const T &before, const T &after,
		                         std::optional<T> LuaCallbackMiniWindowCausalDelta::*field)
		{
			if (before != after)
				delta.*field = after;
		};
		if (create)
		{
			recordValue(create->width, shadow.width, &LuaCallbackMiniWindowCausalDelta::width);
			recordValue(create->height, shadow.height, &LuaCallbackMiniWindowCausalDelta::height);
			recordValue(create->position, shadow.position, &LuaCallbackMiniWindowCausalDelta::position);
			recordValue(create->flags, shadow.flags, &LuaCallbackMiniWindowCausalDelta::flags);
			recordValue(false, shadow.show, &LuaCallbackMiniWindowCausalDelta::show);
			recordValue(QPoint(create->left, create->top), shadow.location,
			            &LuaCallbackMiniWindowCausalDelta::location);
		}
		else
		{
			recordValue(base.width, shadow.width, &LuaCallbackMiniWindowCausalDelta::width);
			recordValue(base.height, shadow.height, &LuaCallbackMiniWindowCausalDelta::height);
			recordValue(base.position, shadow.position, &LuaCallbackMiniWindowCausalDelta::position);
			recordValue(base.flags, shadow.flags, &LuaCallbackMiniWindowCausalDelta::flags);
			recordValue(base.background, shadow.background, &LuaCallbackMiniWindowCausalDelta::background);
			recordValue(base.show, shadow.show, &LuaCallbackMiniWindowCausalDelta::show);
			recordValue(base.location, shadow.location, &LuaCallbackMiniWindowCausalDelta::location);
			recordValue(base.zOrder, shadow.zOrder, &LuaCallbackMiniWindowCausalDelta::zOrder);
			recordValue(base.creatingPlugin, shadow.creatingPlugin,
			            &LuaCallbackMiniWindowCausalDelta::creatingPlugin);
			recordValue(base.installedAt, shadow.installedAt, &LuaCallbackMiniWindowCausalDelta::installedAt);
		}
		delta.resizes = resizeMutations;

		const auto recordMapDelta = []<typename Value>(QHash<QString, std::optional<Value>> &destination,
		                                               const QMap<QString, Value>           &before,
		                                               const QMap<QString, Value>           &after,
		                                               const QSet<QString> &changedIds, const bool force)
		{
			for (const QString &id : changedIds)
			{
				const auto beforeIt = before.constFind(id);
				const auto afterIt  = after.constFind(id);
				if (!force && beforeIt != before.constEnd() && afterIt != after.constEnd() &&
				    beforeIt.value() == afterIt.value())
				{
					continue;
				}
				if (!force && beforeIt == before.constEnd() && afterIt == after.constEnd())
					continue;
				if (afterIt == after.constEnd())
					destination.insert(id, std::nullopt);
				else
					destination.insert(id, afterIt.value());
			}
		};
		recordMapDelta(delta.fonts, base.fonts, shadow.fonts, mutatedFontIds, forceMapValues);
		recordMapDelta(delta.images, base.images, shadow.images, mutatedImageIds, forceMapValues);
		delta.hotspots                  = appliedHotspots;
		delta.hotspotCallbackPlugin     = shadow.callbackPlugin;
		delta.outputHotspotSerialBefore = base.outputHotspotSerial;
		delta.outputHotspotSerialAfter  = shadow.outputHotspotSerial;

		if (delta.width || delta.height || delta.position || delta.flags || delta.background || delta.show ||
		    delta.location || delta.zOrder || delta.creatingPlugin || delta.installedAt ||
		    !delta.resizes.isEmpty())
		{
			delta.snapshotChanges |= LuaCallbackMiniWindowSnapshotChange::WindowInfo;
		}
		if (!delta.fonts.isEmpty())
			delta.snapshotChanges |= LuaCallbackMiniWindowSnapshotChange::Fonts;
		if (!delta.images.isEmpty())
			delta.snapshotChanges |= LuaCallbackMiniWindowSnapshotChange::Images;
		for (auto hotspot = delta.hotspots.constBegin(); hotspot != delta.hotspots.constEnd(); ++hotspot)
		{
			if ((hotspot->expectedInstanceId != 0) != hotspot->hotspot.has_value())
			{
				delta.snapshotChanges |= LuaCallbackMiniWindowSnapshotChange::HotspotMembership;
				break;
			}
		}
		return delta;
	};
	const auto causalDeltaHasEffect = [](const LuaCallbackMiniWindowCausalDelta &delta)
	{
		return delta.width || delta.height || delta.position || delta.flags || delta.background ||
		       delta.show || delta.location || delta.zOrder || delta.creatingPlugin || delta.installedAt ||
		       !delta.resizes.isEmpty() || !delta.fonts.isEmpty() || !delta.images.isEmpty() ||
		       !delta.hotspots.isEmpty() || delta.outputHotspotSerialBefore != delta.outputHotspotSerialAfter;
	};
	const auto recordCausalMutation = [&](const QString &name, LuaCallbackMiniWindowCausalMutation mutation)
	{
		if (m_causalPluginCallbackSnapshotCaptureStack.isEmpty())
			return;
		auto &revision = m_causalPluginCallbackSnapshotCaptureStack.last();
		revision->miniWindowMutations.push_back({name, std::move(mutation)});
		revision->stableDomainMask |=
		    luaCallbackStableSnapshotDomainBit(LuaCallbackStableSnapshotDomain::MiniWindows);
	};
	QHash<QString, LuaCallbackMiniWindowSnapshotChanges> changedWindows;
	QSet<QString>                                        appliedWindowNames;
	QSet<QString>                                        attemptedWindowNames = removedWindowNames;
	for (const QString &name : windows.keys())
		attemptedWindowNames.insert(name);
	for (const QString &name : removedWindowNames)
	{
		const auto currentIt = m_miniWindows.constFind(name);
		if (currentIt == m_miniWindows.constEnd())
		{
			const QSharedPointer<const MiniWindow> baseWindow = baseWindowsByName.value(name);
			if (baseWindow && baseWindow->runtimeId != 0)
			{
				LuaCallbackMiniWindowCausalMutation mutation;
				mutation.kind                    = LuaCallbackMiniWindowCausalMutation::Kind::Remove;
				mutation.delta.expectedRuntimeId = baseWindow->runtimeId;
				recordCausalMutation(name, std::move(mutation));
			}
			appliedWindowNames.insert(name);
			continue;
		}
		const QSharedPointer<const MiniWindow> baseWindow = baseWindowsByName.value(name);
		if (!baseWindow || baseWindow->runtimeId == 0 || currentIt->runtimeId != baseWindow->runtimeId)
			continue;
		const auto previousMouseOver =
		    captureMiniWindowHotspotInteraction(*currentIt, currentIt->mouseOverHotspot);
		const auto previousMouseDown =
		    currentIt->mouseDownHotspot == currentIt->mouseOverHotspot
		        ? std::nullopt
		        : captureMiniWindowHotspotInteraction(*currentIt, currentIt->mouseDownHotspot);
		const quint64 removedRuntimeId = currentIt->runtimeId;
		m_miniWindows.erase(m_miniWindows.find(name));
		LuaCallbackMiniWindowCausalMutation mutation;
		mutation.kind                    = LuaCallbackMiniWindowCausalMutation::Kind::Remove;
		mutation.delta.expectedRuntimeId = removedRuntimeId;
		recordCausalMutation(name, std::move(mutation));
		appliedWindowNames.insert(name);
		changedWindows.insert(name, luaCallbackAllMiniWindowSnapshotChanges());
		if (previousMouseOver)
			reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseOver->hotspotId,
			                                                   previousMouseOver->instanceId,
			                                                   previousMouseOver->tooltip);
		if (previousMouseDown)
			reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseDown->hotspotId,
			                                                   previousMouseDown->instanceId,
			                                                   previousMouseDown->tooltip);
	}

	for (auto it = windows.begin(); it != windows.end(); ++it)
	{
		const QString                            &name            = it.key();
		MiniWindow                                committedWindow = std::move(it.value());
		const MiniWindow                          callbackShadow  = committedWindow;
		auto                                      currentIt       = m_miniWindows.find(name);
		const QSharedPointer<const MiniWindow>    baseWindow      = baseWindowsByName.value(name);
		QHash<QString, MiniWindowHotspotMutation> appliedHotspotMutations;
		LuaCallbackMiniWindowSnapshotChanges      changes =
		    changesByWindow.value(name, luaCallbackAllMiniWindowSnapshotChanges());
		const auto createMutation = createMutationsByWindow.constFind(name);
		if (createMutation != createMutationsByWindow.constEnd())
		{
			const MiniWindow  emptyBase;
			const MiniWindow &base               = baseWindow ? *baseWindow : emptyBase;
			const bool        currentMatchesBase = currentIt != m_miniWindows.end() && baseWindow &&
			                                       baseWindow->runtimeId != 0 &&
			                                       currentIt->runtimeId == baseWindow->runtimeId;
			const bool installFreshIdentity = currentIt == m_miniWindows.end() ||
			                                  (createMutation->freshIdentityRequested && currentMatchesBase);
			const bool exactCallbackBase    = currentMatchesBase && !installFreshIdentity &&
			                                  currentIt->mutationRevision == baseWindow->mutationRevision &&
			                                  !forceDeltaMergeWindowNames.contains(name);
			const auto previousMouseOver =
			    currentIt == m_miniWindows.end()
			        ? std::optional<MiniWindowHotspotInteractionSnapshot>{}
			        : captureMiniWindowHotspotInteraction(*currentIt, currentIt->mouseOverHotspot);
			const auto previousMouseDown =
			    currentIt == m_miniWindows.end()
			        ? std::optional<MiniWindowHotspotInteractionSnapshot>{}
			        : captureMiniWindowHotspotInteraction(*currentIt, currentIt->mouseDownHotspot);

			MiniWindow    mergedWindow = installFreshIdentity ? MiniWindow{} : currentIt.value();
			const quint64 acceptedRuntimeId =
			    installFreshIdentity ? nextMiniWindowRuntimeId() : mergedWindow.runtimeId;
			const quint64 acceptedMutationRevision = installFreshIdentity ? 0 : mergedWindow.mutationRevision;
			const int  acceptedExecutingDepth = installFreshIdentity ? 0 : mergedWindow.executingScriptDepth;
			const bool acceptedExecuting      = installFreshIdentity ? false : mergedWindow.executingScript;
			const double acceptedDevicePixelRatio =
			    viewDevicePixelRatio.value_or(installFreshIdentity ? 1.0 : mergedWindow.devicePixelRatio);
			mergedWindow.devicePixelRatio = acceptedDevicePixelRatio;
			MiniWindowUtils::setDevicePixelRatio(committedWindow, acceptedDevicePixelRatio);
			const bool sharesCallbackBaseIdentity = currentMatchesBase && !installFreshIdentity;
			if (exactCallbackBase)
			{
				appliedHotspotMutations = hotspotMutations.value(name);
				static_cast<void>(preserveRuntimeOnlyState(committedWindow, currentIt.value(), true));
				mergedWindow = std::move(committedWindow);
			}
			else
			{
				appliedHotspotMutations = applyCreateTransition(
				    mergedWindow, base, committedWindow, createMutation.value(), sharesCallbackBaseIdentity,
				    hotspotMutations.value(name), mutatedFontIdsByWindow.value(name),
				    mutatedImageIdsByWindow.value(name), resizeMutationsByWindow.value(name));
			}
			mergedWindow.runtimeId            = acceptedRuntimeId;
			mergedWindow.mutationRevision     = acceptedMutationRevision;
			mergedWindow.executingScriptDepth = acceptedExecutingDepth;
			mergedWindow.executingScript      = acceptedExecuting;

			if (previousMouseOver)
			{
				const auto hotspot = mergedWindow.hotspots.constFind(previousMouseOver->hotspotId);
				if (hotspot == mergedWindow.hotspots.constEnd() ||
				    hotspot->instanceId != previousMouseOver->instanceId)
					mergedWindow.mouseOverHotspot.clear();
			}
			if (previousMouseDown)
			{
				const auto hotspot = mergedWindow.hotspots.constFind(previousMouseDown->hotspotId);
				if (hotspot == mergedWindow.hotspots.constEnd() ||
				    hotspot->instanceId != previousMouseDown->instanceId)
				{
					mergedWindow.mouseDownHotspot.clear();
					mergedWindow.flagsOnMouseDown = 0;
				}
			}

			MiniWindow &acceptedWindow                           = m_miniWindows[name];
			acceptedWindow                                       = std::move(mergedWindow);
			LuaCallbackMiniWindowSnapshotChanges acceptedChanges = luaCallbackAllMiniWindowSnapshotChanges();
			if (!installFreshIdentity)
			{
				LuaCallbackMiniWindowCausalDelta delta = buildCausalDelta(
				    base, callbackShadow, appliedHotspotMutations, mutatedFontIdsByWindow.value(name),
				    mutatedImageIdsByWindow.value(name), resizeMutationsByWindow.value(name),
				    !sharesCallbackBaseIdentity, &createMutation.value());
				delta.expectedRuntimeId = acceptedRuntimeId;
				if (createMutation->clearHotspotsSinceBase)
					delta.outputHotspotSerialBefore = 0;
				acceptedChanges = delta.snapshotChanges | LuaCallbackMiniWindowSnapshotChange::WindowInfo;
				if (createMutation->clearHotspotsSinceBase)
					acceptedChanges |= LuaCallbackMiniWindowSnapshotChange::HotspotMembership;
				delta.snapshotChanges = acceptedChanges;
				LuaCallbackMiniWindowCausalMutation mutation;
				mutation.kind                          = LuaCallbackMiniWindowCausalMutation::Kind::Create;
				mutation.create                        = createMutation.value();
				mutation.create.freshIdentityRequested = false;
				mutation.delta                         = std::move(delta);
				recordCausalMutation(name, std::move(mutation));
			}
			else
			{
				LuaCallbackMiniWindowCausalMutation mutation;
				mutation.kind = LuaCallbackMiniWindowCausalMutation::Kind::Replace;
				mutation.replacement =
				    QSharedPointer<const MiniWindow>::create(acceptedWindow.detachedImageCopy());
				recordCausalMutation(name, std::move(mutation));
			}
			if (previousMouseOver)
				reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseOver->hotspotId,
				                                                   previousMouseOver->instanceId,
				                                                   previousMouseOver->tooltip);
			if (previousMouseDown &&
			    (!previousMouseOver || previousMouseDown->hotspotId != previousMouseOver->hotspotId))
				reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseDown->hotspotId,
				                                                   previousMouseDown->instanceId,
				                                                   previousMouseDown->tooltip);
			appliedWindowNames.insert(name);
			changedWindows.insert(name, acceptedChanges);
			continue;
		}
		if (currentIt == m_miniWindows.end() || replacedWindowNames.contains(name))
			changes = luaCallbackAllMiniWindowSnapshotChanges();
		if (currentIt != m_miniWindows.end())
		{
			const bool replacement = replacedWindowNames.contains(name);
			if (!replacement &&
			    (!baseWindow || baseWindow->runtimeId == 0 || currentIt->runtimeId != baseWindow->runtimeId))
			{
				addedHotspots.remove(name);
				continue;
			}
			if (!replacement && (forceDeltaMergeWindowNames.contains(name) ||
			                     currentIt->mutationRevision != baseWindow->mutationRevision))
			{
				MiniWindow mergedWindow = currentIt.value();
				appliedHotspotMutations = mergeStaleShadow(
				    mergedWindow, *baseWindow, committedWindow, presentationChangedWindowNames.contains(name),
				    hotspotMutations.value(name), mutatedFontIdsByWindow.value(name),
				    mutatedImageIdsByWindow.value(name), resizeMutationsByWindow.value(name));
				committedWindow = std::move(mergedWindow);
			}
			else if (!replacement)
			{
				appliedHotspotMutations = hotspotMutations.value(name);
			}
			const MiniWindow &current          = currentIt.value();
			const QString     currentMouseOver = current.mouseOverHotspot;
			const QString     currentMouseDown = current.mouseDownHotspot;
			const auto previousMouseOver = captureMiniWindowHotspotInteraction(current, currentMouseOver);
			const auto previousMouseDown =
			    currentMouseDown == currentMouseOver
			        ? std::nullopt
			        : captureMiniWindowHotspotInteraction(current, currentMouseDown);
			if (preserveRuntimeOnlyState(committedWindow, current, !replacedWindowNames.contains(name)))
				changes |= LuaCallbackMiniWindowSnapshotChange::WindowInfo;
			currentIt.value() = std::move(committedWindow);
			if (replacement)
			{
				LuaCallbackMiniWindowCausalMutation mutation;
				mutation.kind = LuaCallbackMiniWindowCausalMutation::Kind::Replace;
				mutation.replacement =
				    QSharedPointer<const MiniWindow>::create(currentIt.value().detachedImageCopy());
				recordCausalMutation(name, std::move(mutation));
			}
			else
			{
				LuaCallbackMiniWindowCausalMutation mutation;
				mutation.delta = buildCausalDelta(
				    *baseWindow, callbackShadow, appliedHotspotMutations, mutatedFontIdsByWindow.value(name),
				    mutatedImageIdsByWindow.value(name), resizeMutationsByWindow.value(name));
				if (causalDeltaHasEffect(mutation.delta))
					recordCausalMutation(name, std::move(mutation));
			}
			if (previousMouseOver)
				reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseOver->hotspotId,
				                                                   previousMouseOver->instanceId,
				                                                   previousMouseOver->tooltip);
			if (previousMouseDown)
				reconcileMiniWindowHotspotInteractionAfterMutation(name, previousMouseDown->hotspotId,
				                                                   previousMouseDown->instanceId,
				                                                   previousMouseDown->tooltip);
		}
		else
		{
			if (!replacedWindowNames.contains(name))
			{
				addedHotspots.remove(name);
				continue;
			}
			committedWindow.runtimeId        = nextMiniWindowRuntimeId();
			committedWindow.mutationRevision = 0;
			if (viewDevicePixelRatio)
				MiniWindowUtils::setDevicePixelRatio(committedWindow, *viewDevicePixelRatio);
			m_miniWindows[name] = std::move(committedWindow);
			LuaCallbackMiniWindowCausalMutation mutation;
			mutation.kind = LuaCallbackMiniWindowCausalMutation::Kind::Replace;
			mutation.replacement =
			    QSharedPointer<const MiniWindow>::create(m_miniWindows.value(name).detachedImageCopy());
			recordCausalMutation(name, std::move(mutation));
		}
		appliedWindowNames.insert(name);
		changedWindows[name] |= changes;
	}

	if (!changedWindows.isEmpty())
	{
		emitMiniWindowsChangedCoalesced(changedWindows);
		requestMiniWindowAddedHotspotHoverChecks(std::move(addedHotspots));
	}
	if (outcomes)
	{
		outcomes->clear();
		outcomes->reserve(attemptedWindowNames.size());
		for (const QString &name : std::as_const(attemptedWindowNames))
		{
			MiniWindowCommitOutcome outcome;
			outcome.applied = appliedWindowNames.contains(name);
			if (const auto current = m_miniWindows.constFind(name); current != m_miniWindows.constEnd())
			{
				outcome.exists    = true;
				outcome.runtimeId = current->runtimeId;
			}
			outcomes->insert(name, outcome);
		}
	}
}

void WorldRuntime::reconcileMiniWindowHotspotInteractionAfterMutation(const QString &windowName,
                                                                      const QString &hotspotId,
                                                                      const quint64  previousInstanceId,
                                                                      const QString &previousTooltip) const
{
	if (!m_view || hotspotId.isEmpty() || previousInstanceId == 0)
		return;
	const MiniWindow *window = miniWindow(windowName);
	if (!window)
	{
		m_view->invalidateMiniWindowHotspotInteraction(windowName, hotspotId, previousInstanceId);
		return;
	}
	const auto currentHotspot = window->hotspots.constFind(hotspotId);
	if (currentHotspot == window->hotspots.constEnd() || currentHotspot->instanceId != previousInstanceId)
	{
		m_view->invalidateMiniWindowHotspotInteraction(windowName, hotspotId, previousInstanceId);
		return;
	}
	if (currentHotspot->tooltip != previousTooltip)
		m_view->refreshMiniWindowHotspotTooltip(windowName, hotspotId, previousInstanceId,
		                                        currentHotspot->tooltip);
}

void WorldRuntime::requestMiniWindowAddedHotspotHoverChecks(MiniWindowHotspotInstanceMap addedHotspots)
{
	if (!m_view || m_view->isMiniWindowCaptureActive() || !m_view->hasLastMousePosition() ||
	    addedHotspots.isEmpty())
		return;
	if (m_pendingMiniWindowAddedHotspots.isEmpty())
	{
		m_pendingMiniWindowAddedHotspots.swap(addedHotspots);
	}
	else
	{
		for (auto windowIt = addedHotspots.cbegin(); windowIt != addedHotspots.cend(); ++windowIt)
		{
			auto &pendingForWindow = m_pendingMiniWindowAddedHotspots[windowIt.key()];
			for (auto hotspotIt = windowIt->cbegin(); hotspotIt != windowIt->cend(); ++hotspotIt)
				pendingForWindow.insert(hotspotIt.key(), hotspotIt.value());
		}
	}
	if (m_miniWindowMutationBatchDepth == 0)
		scheduleMiniWindowAddedHotspotHoverCheck();
}

void WorldRuntime::requestMiniWindowAddedHotspotHoverCheck(const QString &windowName,
                                                           const QString &hotspotId, const quint64 instanceId)
{
	if (!m_view || m_view->isMiniWindowCaptureActive() || !m_view->hasLastMousePosition() ||
	    windowName.isEmpty() || hotspotId.isEmpty() || instanceId == 0)
		return;
	m_pendingMiniWindowAddedHotspots[windowName].insert(hotspotId, instanceId);
	if (m_miniWindowMutationBatchDepth == 0)
		scheduleMiniWindowAddedHotspotHoverCheck();
}

void WorldRuntime::scheduleMiniWindowAddedHotspotHoverCheck()
{
	if (m_pendingMiniWindowAddedHotspots.isEmpty() || m_miniWindowAddedHotspotHoverCheckQueued)
		return;
	if (!m_view || m_view->isMiniWindowCaptureActive() || !m_view->hasLastMousePosition())
	{
		m_pendingMiniWindowAddedHotspots.clear();
		return;
	}
	m_miniWindowAddedHotspotHoverCheckQueued = true;
	const QPointer<WorldRuntime> runtimeGuard(this);
	const QPointer<WorldView>    viewGuard(m_view);
	const quint64                viewBindingGeneration = m_viewBindingGeneration;
	QMetaObject::invokeMethod(
	    this,
	    [runtimeGuard, viewGuard, viewBindingGeneration]
	    {
		    if (!runtimeGuard)
			    return;
		    runtimeGuard->m_miniWindowAddedHotspotHoverCheckQueued = false;
		    if (!viewGuard || runtimeGuard->m_view != viewGuard ||
		        runtimeGuard->m_viewBindingGeneration != viewBindingGeneration)
		    {
			    runtimeGuard->scheduleMiniWindowAddedHotspotHoverCheck();
			    return;
		    }
		    MiniWindowHotspotInstanceMap addedHotspots;
		    addedHotspots.swap(runtimeGuard->m_pendingMiniWindowAddedHotspots);
		    viewGuard->recheckMiniWindowHoverForAddedHotspots(addedHotspots);
	    },
	    Qt::QueuedConnection);
}

QStringList WorldRuntime::windowList() const
{
	return m_miniWindows.keys();
}

QVariant WorldRuntime::windowInfo(const QString &name, int infoType) const
{
	const MiniWindow *window = miniWindow(name);
	if (!window)
		return {};

	switch (infoType)
	{
	case 1:
		return window->location.x();
	case 2:
		return window->location.y();
	case 3:
		return window->width;
	case 4:
		return window->height;
	case 5:
		return window->show;
	case 6:
		return window->temporarilyHide;
	case 7:
		return window->position;
	case 8:
		return window->flags;
	case 9:
		if (window->background.isValid())
			return QVariant::fromValue<qlonglong>(colorToRef(window->background));
		return 0;
	case 10:
		return window->apiRect().left();
	case 11:
		return window->apiRect().top();
	case 12:
		return window->apiRect().right();
	case 13:
		return window->apiRect().bottom();
	case 14:
		return window->lastMousePosition.x();
	case 15:
		return window->lastMousePosition.y();
	case 16:
		return window->lastMouseUpdate;
	case 17:
		return window->clientMousePosition.x();
	case 18:
		return window->clientMousePosition.y();
	case 19:
		return window->mouseOverHotspot;
	case 20:
		return window->mouseDownHotspot;
	case 21:
		return window->installedAt.isValid() ? QVariant(toLuaSystemTime(window->installedAt)) : QVariant();
	case 22:
		return window->zOrder;
	case 23:
		return window->creatingPlugin;
	default:
		return {};
	}
}

MiniWindow *WorldRuntime::miniWindowMutable(const QString &name)
{
	const auto it = m_miniWindows.find(name);
	if (it == m_miniWindows.end())
		return nullptr;
	return &it.value();
}

const MiniWindow *WorldRuntime::miniWindow(const QString &name) const
{
	const auto it = m_miniWindows.find(name);
	if (it == m_miniWindows.end())
		return nullptr;
	return &it.value();
}

QVector<MiniWindow *> WorldRuntime::sortedMiniWindowsMutable()
{
	QVector<MiniWindow *> ordered;
	ordered.reserve(m_miniWindows.size());
	for (auto it = m_miniWindows.begin(); it != m_miniWindows.end(); ++it)
		ordered.push_back(&it.value());

	std::ranges::sort(ordered,
	                  [](const MiniWindow *a, const MiniWindow *b)
	                  {
		                  if (a->zOrder == b->zOrder)
			                  return a->name < b->name;
		                  return a->zOrder < b->zOrder;
	                  });

	return ordered;
}

WorldRuntime::MiniWindowGeometryConstraintSnapshot WorldRuntime::miniWindowGeometryConstraintSnapshot() const
{
	if (QThread::currentThread() != thread())
	{
		return qmudInvokeMethodOr(const_cast<WorldRuntime *>(this), MiniWindowGeometryConstraintSnapshot{},
		                          [this] { return miniWindowGeometryConstraintSnapshot(); });
	}

	qmudAssertObjectThreadAffinity(this, "WorldRuntime::miniWindowGeometryConstraintSnapshot");
	MiniWindowGeometryConstraintSnapshot snapshot;
	if (!m_view)
		return snapshot;
	m_view->synchronizePendingInputViewportLayout();

	auto *const mutableThis = const_cast<WorldRuntime *>(this);
	const QSize clientSize(m_view->outputClientWidth(), m_view->outputClientHeight());
	const QSize ownerSize = m_view->size();
	const auto  windows   = mutableThis->sortedMiniWindowsMutable();
	struct WindowPresentationState
	{
			MiniWindow *window{nullptr};
			QRect       rect;
			bool        temporarilyHide{false};
	};
	QVector<WindowPresentationState> windowStates;
	windowStates.reserve(windows.size());
	for (MiniWindow *window : windows)
	{
		if (window)
			windowStates.push_back({window, window->rect, window->temporarilyHide});
	}
	const int    referenceRightUnder      = m_absoluteReferenceRightUnder;
	const int    referenceBottomUnder     = m_absoluteReferenceBottomUnder;
	const int    referenceRightOver       = m_absoluteReferenceRightOver;
	const int    referenceBottomOver      = m_absoluteReferenceBottomOver;
	const double scaleXUnder              = m_absoluteMiniWindowScaleXUnder;
	const double scaleYUnder              = m_absoluteMiniWindowScaleYUnder;
	const double scaleXOver               = m_absoluteMiniWindowScaleXOver;
	const double scaleYOver               = m_absoluteMiniWindowScaleYOver;
	const auto   restorePresentationState = qScopeGuard(
	    [mutableThis, &windowStates, referenceRightUnder, referenceBottomUnder, referenceRightOver,
	     referenceBottomOver, scaleXUnder, scaleYUnder, scaleXOver, scaleYOver]
	    {
		    mutableThis->m_absoluteReferenceRightUnder   = referenceRightUnder;
		    mutableThis->m_absoluteReferenceBottomUnder  = referenceBottomUnder;
		    mutableThis->m_absoluteReferenceRightOver    = referenceRightOver;
		    mutableThis->m_absoluteReferenceBottomOver   = referenceBottomOver;
		    mutableThis->m_absoluteMiniWindowScaleXUnder = scaleXUnder;
		    mutableThis->m_absoluteMiniWindowScaleYUnder = scaleYUnder;
		    mutableThis->m_absoluteMiniWindowScaleXOver  = scaleXOver;
		    mutableThis->m_absoluteMiniWindowScaleYOver  = scaleYOver;
		    for (const WindowPresentationState &state : windowStates)
		    {
			    state.window->rect            = state.rect;
			    state.window->temporarilyHide = state.temporarilyHide;
		    }
	    });
	Q_UNUSED(restorePresentationState);
	mutableThis->layoutMiniWindows(clientSize, ownerSize, true, &windows, false);
	mutableThis->layoutMiniWindows(clientSize, ownerSize, false, &windows, false);

	snapshot.displayClientHeight = clientSize.height();
	snapshot.displayClientWidth  = clientSize.width();
	snapshot.scaleXOver          = mutableThis->m_absoluteMiniWindowScaleXOver;
	snapshot.scaleYOver          = mutableThis->m_absoluteMiniWindowScaleYOver;
	snapshot.scaleXUnder         = mutableThis->m_absoluteMiniWindowScaleXUnder;
	snapshot.scaleYUnder         = mutableThis->m_absoluteMiniWindowScaleYUnder;
	return snapshot;
}

void WorldRuntime::layoutMiniWindows(const QSize &clientSize, const QSize &ownerSize, bool underneath,
                                     const QVector<MiniWindow *> *orderedWindows,
                                     const bool                   publishPresentation)
{
	const int             clientWidth  = clientSize.width();
	const int             clientHeight = clientSize.height();
	const int             ownerWidth   = ownerSize.width();
	const int             ownerHeight  = ownerSize.height();
	QVector<MiniWindow *> fallbackWindows;
	if (!orderedWindows)
	{
		fallbackWindows = sortedMiniWindowsMutable();
		orderedWindows  = &fallbackWindows;
	}
	const QVector<MiniWindow *> &windows = *orderedWindows;

	int                          absoluteMaxRight     = 0;
	int                          absoluteMaxBottom    = 0;
	bool                         sawAbsolute          = false;
	const auto                   saturatedAbsoluteEnd = [](const int origin, const int extent)
	{
		const qint64 end = static_cast<qint64>(origin) + static_cast<qint64>(qMax(0, extent));
		return static_cast<int>(qBound(qint64{0}, end, static_cast<qint64>(std::numeric_limits<int>::max())));
	};
	for (MiniWindow const *window : windows)
	{
		if (!window || !window->show)
			continue;
		const bool drawUnder = (window->flags & kMiniWindowDrawUnderneath) != 0;
		if (drawUnder != underneath)
			continue;
		if ((window->flags & kMiniWindowAbsoluteLocation) == 0)
			continue;
		sawAbsolute = true;

		absoluteMaxRight = qMax(absoluteMaxRight, saturatedAbsoluteEnd(window->location.x(), window->width));
		absoluteMaxBottom =
		    qMax(absoluteMaxBottom, saturatedAbsoluteEnd(window->location.y(), window->height));
	}

	int       &referenceRight  = underneath ? m_absoluteReferenceRightUnder : m_absoluteReferenceRightOver;
	int       &referenceBottom = underneath ? m_absoluteReferenceBottomUnder : m_absoluteReferenceBottomOver;
	const bool captureActive   = m_view && m_view->isMiniWindowDragCaptureActive();
	if (!sawAbsolute)
	{
		referenceRight  = 0;
		referenceBottom = 0;
	}
	else if (captureActive)
	{
		// Keep drag scaling stable while a miniwindow is being moved/resized.
		referenceRight  = qMax(referenceRight, absoluteMaxRight);
		referenceBottom = qMax(referenceBottom, absoluteMaxBottom);
	}
	else
	{
		// Outside drag, use current extents to avoid stale startup/session anchors.
		referenceRight  = absoluteMaxRight;
		referenceBottom = absoluteMaxBottom;
	}

	double absoluteScaleX        = 1.0;
	double absoluteScaleY        = 1.0;
	bool   forceUnscaledAbsolute = false;
	if (AppController const *app = AppController::instance())
	{
		if (app->getGlobalOption(QStringLiteral("DisableWindowScaler")).toInt() != 0)
			forceUnscaledAbsolute = true;
	}
	if (m_view)
	{
		if (QWidget const *rootWindow = m_view->window(); rootWindow)
			forceUnscaledAbsolute = forceUnscaledAbsolute || rootWindow->isMaximized();
	}
	if (!forceUnscaledAbsolute)
	{
		if (clientWidth > 0 && referenceRight > clientWidth)
			absoluteScaleX = static_cast<double>(clientWidth) / static_cast<double>(referenceRight);
		if (clientHeight > 0 && referenceBottom > clientHeight)
			absoluteScaleY = static_cast<double>(clientHeight) / static_cast<double>(referenceBottom);
	}
	if (underneath)
	{
		m_absoluteMiniWindowScaleXUnder = absoluteScaleX;
		m_absoluteMiniWindowScaleYUnder = absoluteScaleY;
	}
	else
	{
		m_absoluteMiniWindowScaleXOver = absoluteScaleX;
		m_absoluteMiniWindowScaleYOver = absoluteScaleY;
	}

	auto scaledAbsoluteRect = [clientWidth, clientHeight, absoluteScaleX,
	                           absoluteScaleY](const MiniWindow *window) -> QRect
	{
		if (!window || clientWidth <= 0 || clientHeight <= 0)
			return {};

		const int canonicalWidth  = qMax(0, window->width);
		const int canonicalHeight = qMax(0, window->height);

		int       scaledWidth  = qRound(static_cast<double>(canonicalWidth) * absoluteScaleX);
		int       scaledHeight = qRound(static_cast<double>(canonicalHeight) * absoluteScaleY);
		if (canonicalWidth > 0 && scaledWidth <= 0)
			scaledWidth = 1;
		if (canonicalHeight > 0 && scaledHeight <= 0)
			scaledHeight = 1;
		if (scaledWidth > clientWidth)
			scaledWidth = clientWidth;
		if (scaledHeight > clientHeight)
			scaledHeight = clientHeight;

		int scaledLeft = qRound(static_cast<double>(window->location.x()) * absoluteScaleX);
		int scaledTop  = qRound(static_cast<double>(window->location.y()) * absoluteScaleY);

		if (scaledLeft < 0)
			scaledLeft = 0;
		if (scaledTop < 0)
			scaledTop = 0;

		if (scaledLeft > clientWidth - scaledWidth)
			scaledLeft = qMax(0, clientWidth - scaledWidth);
		if (scaledTop > clientHeight - scaledHeight)
			scaledTop = qMax(0, clientHeight - scaledHeight);

		return {scaledLeft, scaledTop, scaledWidth, scaledHeight};
	};

	QPoint                topLeft(0, 0);
	QPoint                topRight(clientWidth, 0);
	QPoint                bottomLeft(0, clientHeight);
	QPoint                bottomRight(clientWidth, clientHeight);

	int                   topWidths    = 0;
	int                   rightHeights = 0;
	int                   bottomWidths = 0;
	int                   leftHeights  = 0;

	QVector<MiniWindow *> topWindows;
	QVector<MiniWindow *> rightWindows;
	QVector<MiniWindow *> bottomWindows;
	QVector<MiniWindow *> leftWindows;

	for (MiniWindow *window : windows)
	{
		window->temporarilyHide = false;

		if (!window->show)
			continue;

		const bool drawUnder = (window->flags & kMiniWindowDrawUnderneath) != 0;
		if (drawUnder != underneath)
			continue;

		const int w = window->width;
		const int h = window->height;

		if (window->flags & kMiniWindowAbsoluteLocation)
		{
			// Unscaled absolute windows retain their canonical plugin geometry and are clipped by the
			// output layers. The optional scaler alone may transform their displayed geometry.
			window->rect =
			    forceUnscaledAbsolute
			        ? QRect(window->location, QSize(qMax(0, window->width), qMax(0, window->height)))
			        : scaledAbsoluteRect(window);
			continue;
		}

		switch (window->position)
		{
		case 0:
			window->rect = QRect(0, 0, clientWidth, clientHeight);
			continue;
		case 1:
			if (h > 0)
			{
				const double ratio = static_cast<double>(w) / static_cast<double>(h);
				window->rect       = QRect(0, 0, static_cast<int>(clientHeight * ratio), clientHeight);
			}
			else
				window->rect = QRect(0, 0, clientWidth, clientHeight);
			continue;
		case 2:
			window->rect = QRect(0, 0, ownerWidth, ownerHeight);
			continue;
		case 3:
			if (h > 0)
			{
				const double ratio = static_cast<double>(w) / static_cast<double>(h);
				window->rect       = QRect(0, 0, static_cast<int>(ownerHeight * ratio), ownerHeight);
			}
			else
				window->rect = QRect(0, 0, ownerWidth, ownerHeight);
			continue;
		case 4:
			window->rect = QRect(0, 0, w, h);
			topLeft.setX(qMax(topLeft.x(), window->rect.x() + window->rect.width()));
			topLeft.setY(qMax(topLeft.y(), window->rect.y() + window->rect.height()));
			break;
		case 5:
			topWidths += w;
			topWindows.push_back(window);
			break;
		case 6:
			window->rect = QRect(clientWidth - w, 0, w, h);
			topRight.setX(qMin(topRight.x(), window->rect.x()));
			topRight.setY(qMax(topRight.y(), window->rect.y() + window->rect.height()));
			break;
		case 7:
			rightHeights += h;
			rightWindows.push_back(window);
			break;
		case 8:
			window->rect = QRect(clientWidth - w, clientHeight - h, w, h);
			bottomRight.setX(qMin(bottomRight.x(), window->rect.x()));
			bottomRight.setY(qMin(bottomRight.y(), window->rect.y()));
			break;
		case 9:
			bottomWidths += w;
			bottomWindows.push_back(window);
			break;
		case 10:
			window->rect = QRect(0, clientHeight - h, w, h);
			bottomLeft.setX(qMax(bottomLeft.x(), window->rect.x() + window->rect.width()));
			bottomLeft.setY(qMin(bottomLeft.y(), window->rect.y()));
			break;
		case 11:
			leftHeights += h;
			leftWindows.push_back(window);
			break;
		case 12:
			window->rect = QRect((clientWidth - w) / 2, (clientHeight - h) / 2, w, h);
			break;
		default:
			break;
		}
	}

	const int topRoom    = topRight.x() - topLeft.x();
	const int rightRoom  = bottomRight.y() - topRight.y();
	const int bottomRoom = bottomRight.x() - bottomLeft.x();
	const int leftRoom   = bottomLeft.y() - topLeft.y();

	auto discardOverflow = [](QVector<MiniWindow *> &dockedWindows, int &totalSize, int room, bool vertical)
	{
		while (!dockedWindows.isEmpty() && totalSize > room)
		{
			MiniWindow *window = dockedWindows.back();
			dockedWindows.removeLast();
			totalSize -= vertical ? window->height : window->width;
			window->temporarilyHide = true;
		}
	};

	discardOverflow(topWindows, topWidths, topRoom, false);
	discardOverflow(rightWindows, rightHeights, rightRoom, true);
	discardOverflow(bottomWindows, bottomWidths, bottomRoom, false);
	discardOverflow(leftWindows, leftHeights, leftRoom, true);

	auto distribute = [](QVector<MiniWindow *> &dockedWindows, int room, int startPos, bool vertical,
	                     int fixedX, int fixedY, bool alignRight, bool alignBottom)
	{
		if (dockedWindows.isEmpty())
			return;
		int totalSize = 0;
		for (const MiniWindow *window : dockedWindows)
			totalSize += vertical ? window->height : window->width;
		const int gap   = (room - totalSize) / (safeQSizeToInt(dockedWindows.size()) + 1);
		int       start = startPos + gap;
		for (MiniWindow *window : dockedWindows)
		{
			if (vertical)
			{
				const int x  = alignRight ? fixedX - window->width : fixedX;
				window->rect = QRect(x, start, window->width, window->height);
				start += window->height + gap;
			}
			else
			{
				const int y  = alignBottom ? fixedY - window->height : fixedY;
				window->rect = QRect(start, y, window->width, window->height);
				start += window->width + gap;
			}
		}
	};

	distribute(topWindows, topRoom, topLeft.x(), false, 0, 0, false, false);
	distribute(rightWindows, rightRoom, topRight.y(), true, clientWidth, 0, true, false);
	distribute(bottomWindows, bottomRoom, bottomLeft.x(), false, 0, clientHeight, false, true);
	distribute(leftWindows, leftRoom, topLeft.y(), true, 0, 0, false, false);

	if (publishPresentation)
	{
		using Presentation = LuaCallbackMiniWindowsSnapshotState::PresentationSnapshot;
		using Store        = LuaCallbackPersistentSlotMap<Presentation>;
		QVector<Store::Update> updates;
		updates.reserve(windows.size() * 2);
		for (const MiniWindow *window : windows)
		{
			if (!window || window->runtimeId == 0)
				continue;
			Presentation row;
			row.runtimeId           = window->runtimeId;
			row.rect                = window->rect;
			row.temporarilyHide     = window->temporarilyHide;
			row.lastMousePosition   = window->lastMousePosition;
			row.lastMouseUpdate     = window->lastMouseUpdate;
			row.clientMousePosition = window->clientMousePosition;
			row.mouseOverHotspot    = window->mouseOverHotspot;
			row.mouseDownHotspot    = window->mouseDownHotspot;
			const auto slot         = static_cast<quint32>(window->runtimeId);
			const auto old          = m_luaCallbackMiniWindowPresentationByRuntimeId.value(slot);
			if (old && *old == row)
				continue;
			const quint64 previousRuntimeId =
			    m_luaCallbackMiniWindowPresentationRuntimeIdByName.value(window->name);
			if (previousRuntimeId != 0 && previousRuntimeId != window->runtimeId)
				updates.push_back({static_cast<quint32>(previousRuntimeId), {}});
			updates.push_back({slot, QSharedPointer<const Presentation>::create(row)});
			m_luaCallbackMiniWindowPresentationRuntimeIdByName.insert(window->name, window->runtimeId);
			if (!m_causalPluginCallbackSnapshotCaptureStack.isEmpty())
				m_causalPluginCallbackSnapshotCaptureStack.last()->miniWindowPresentationMutations.insert(
				    window->name, {window->runtimeId, std::move(row)});
		}
		m_luaCallbackMiniWindowPresentationByRuntimeId =
		    m_luaCallbackMiniWindowPresentationByRuntimeId.withUpdates(updates);
	}
}

QPoint WorldRuntime::canonicalMiniWindowClientPosition(const QPoint &displayPosition,
                                                       const int     windowFlags) const
{
	if ((windowFlags & kMiniWindowAbsoluteLocation) == 0)
		return displayPosition;

	const bool underneath = (windowFlags & kMiniWindowDrawUnderneath) != 0;
	return MiniWindowUtils::capturedDragPositionToCanonical(
	    displayPosition, underneath ? m_absoluteMiniWindowScaleXUnder : m_absoluteMiniWindowScaleXOver,
	    underneath ? m_absoluteMiniWindowScaleYUnder : m_absoluteMiniWindowScaleYOver);
}

int WorldRuntime::windowRectOp(const QString &name, int action, int left, int top, int right, int bottom,
                               long colour1, long colour2)
{
	MiniWindow *window = miniWindowMutable(name);
	if (!window)
		return eNoSuchWindow;
	const int result = MiniWindowUtils::rectOp(*window, action, left, top, right, bottom, colour1, colour2);
	if (result == eOK)
		emitMiniWindowsChangedCoalesced(name, {});
	return result;
}

